'use strict';

/* D2 Source Mastery Lane. PDF page numbers refer to the local Seventh Edition. */
const ELEC275_D2_SOURCE=(()=>{
 const S=(title,math,why)=>({title,math,why});
 const sourceMeta=o=>{
  const number=o.id.split('-')[1];
  const [chapter,itemText]=number.split('.');
  const item=Number(itemText);
  let section=o.section;
  if(!section&&chapter==='1'){
   if(o.kind==='example') section=item<=16?'1.7':item<=19?'1.8':'1.9';
   if(o.kind==='cyu') section=item<=9?'1.7':item<=12?'1.8':'1.9';
   if(o.kind==='homework') section=item<=67?'1.7':item<=83?'1.8':'1.9';
  }
  if(!section&&chapter==='2') section=(o.kind==='example'&&item===9)||(o.kind==='homework'&&item>=43)?'2.6':'2.4';
  const labels={example:'Example',cyu:'CYU',homework:'Problem'};
  return {label:`Rizzoni ${labels[o.kind]} ${number}`,section:`§${section}`,page:o.page||o.fig};
 };
 const Q=o=>({lane:'source',reviewStatus:'independently-checked',difficulty:o.difficulty||(o.kind==='homework'?'Core':'Guided'),time:o.time||(o.kind==='homework'?7:6),calculator:o.calculator||'Scientific calculator optional',assumptions:o.assumptions||'DC steady state; ideal wires and sources unless stated otherwise. Keep the reference polarities and current directions shown in the figure.',...o,source:sourceMeta(o),figure:{page:o.fig||o.page,alt:o.alt||`Rizzoni circuit for ${o.id}`}});
 return [
Q({id:'EX-1.13',kind:'example',topic:'Two-node nodal analysis',page:103,title:'Solve a two-node current-source network',prompt:'Use nodal analysis to find v₁ and v₂ in Figure 1.57, then find the four resistor currents under the references shown.',givens:'i₁=10 mA upward and i₂=50 mA downward; R₁=1 kΩ,R₂=2 kΩ,R₃=10 kΩ,R₄=2 kΩ.',unknowns:'Node voltages v₁,v₂ and resistor currents iR1 through iR4.',answer:'v₁=−95/7=−13.5714 V; v₂=−370/7=−52.8571 V; iR1=−13.5714 mA,iR2=19.6429 mA,iR3=3.92857 mA,iR4=−26.4286 mA.',readAloud:'R two and R three both connect node one to node two. At node one, resistor currents leaving equal the ten milliampere source current entering. At node two, the downward source draws fifty milliamperes.',symbols:'v₁,v₂ are node voltages to ground; iRj is the signed current in Rⱼ under the figure reference; 1 mA·1 kΩ=1 V.',steps:[S('Write both KCL equations','v_1+\\frac{v_1-v_2}{2}+\\frac{v_1-v_2}{10}=10,\\qquad \\frac{v_2}{2}+\\frac{v_2-v_1}{2}+\\frac{v_2-v_1}{10}=-50','Using kΩ and mA, the first balance includes both resistors joining the nodes. The second includes R4 and the current drawn downward by i2.'),S('Solve and recover branch currents','1.6v_1-0.6v_2=10,\\quad -0.6v_1+1.1v_2=-50\\Rightarrow v_1=-95/7\\ \\mathrm{V},\\ v_2=-370/7\\ \\mathrm{V}','Ohm’s law gives iR1=v₁/1 kΩ, iR2=(v₁−v₂)/2 kΩ, iR3=(v₁−v₂)/10 kΩ, and iR4=v₂/2 kΩ.')],verification:'The exact voltages satisfy 1.6(−95/7)−0.6(−370/7)=10 mA and −0.6(−95/7)+1.1(−370/7)=−50 mA. The four Ohm’s-law currents follow from the same voltage differences.',trap:'R3 connects the two nodes, so its current uses v₁−v₂; do not replace that difference by v₂ alone.'}),
Q({id:'EX-1.14',kind:'example',topic:'Nodal equations in kΩ and mA',page:105,fig:106,title:'Solve a two-node system without unit conversion clutter',prompt:'Find va and vb for Figure 1.59 by writing and solving the two nodal equations.',givens:'ia=1 mA, ib=2 mA; R₁=1 kΩ, R₂=500 Ω, R₃=2.2 kΩ, R₄=4.7 kΩ.',unknowns:'Node voltages va and vb.',answer:'va=1.667 V and vb=2.000 V.',readAloud:'Three va minus two vb equals one, and minus two va plus two point six seven vb equals two. The coefficients mix conductance and scale factors but the equations remain dimensionally consistent.',symbols:'va,vb are volts; ia,ib are milliamps; R₂=0.5 kΩ. The coefficient 2.67 is the rounded 1/0.5+1/2.2+1/4.7 conductance-scaled form used by the text.',steps:[S('Balance currents at both nodes','(3)v_a-(2)v_b=1,\\qquad -(2)v_a+(2.67)v_b=2','The book combines parallel conductances and scales the equations to obtain these compact kΩ/mA forms. Write currents leaving through resistors on the left and source currents entering on the right.'),S('Eliminate one node voltage','v_b=2.000\\ \\mathrm{V},\\qquad v_a=(1+2v_b)/3=1.667\\ \\mathrm{V}','The second equation and first equation are solved simultaneously; back-substitution avoids solving for resistor currents first.')],verification:'3(1.667)−2(2.000)=1.001≈1 and −2(1.667)+2.67(2.000)=2.006≈2; the small residuals come from the textbook’s rounded coefficients.',trap:'Do not read 2.67 vb as a resistance drop: it is a coefficient in the scaled nodal equation, not 2.67 kΩ times a current.'}),
Q({id:'EX-1.15',kind:'example',topic:'Three-node nodal analysis',page:107,title:'Find the requested node voltage in a three-node ladder',prompt:'Apply nodal analysis to Figure 1.61 and determine v, the voltage at node 2.',givens:'R₁=2 Ω joins v₁ to v₃; R₂=1 Ω joins v₁ to v₂; R₃=4 Ω and R₄=3 Ω are shunts; i₁=2 A and i₂=3 A use the textbook equation references.',unknowns:'v₁,v₂,v₃ and requested v=v₂.',answer:'v=v₂=−0.400 V; also v₁=−3.500 V and v₃=−5.700 V.',readAloud:'Each resistor current is a node-voltage difference divided by resistance. Write all currents leaving a node, then place the signed source injection on the other side.',symbols:'v₁,v₂,v₃ are node voltages relative to the bottom ground; v is the requested v₂; currents are in amperes and resistances in ohms.',steps:[S('Form three nodal balances','\\frac{v_1-v_3}{2}+(v_1-v_2)=-2,\\quad (v_2-v_1)+\\frac{v_2}{4}=3,\\quad \\frac{v_3-v_1}{2}+\\frac{v_3}{3}=-3','R1 appears in the v1 and v3 equations, R2 couples v1 and v2, and the two shunt resistors appear only at their own nodes.'),S('Solve the coupled system','v_1=-3.5\\ \\mathrm{V},\\qquad v_2=-0.4\\ \\mathrm{V},\\qquad v_3=-5.7\\ \\mathrm{V}','Solving all three equations together is necessary because each coupling resistor makes a node voltage depend on its neighbour.')],verification:'Direct substitution gives (−3.5+5.7)/2+(−3.5+0.4)=−2 A, (−0.4+3.5)−0.4/4=3 A, and (−5.7+3.5)/2−5.7/3=−3 A.',trap:'R3 is the shunt at v₂; do not write a v₂−v₃ current through R3 when the figure connects R3 to ground.'}),
Q({id:'EX-1.16',kind:'example',topic:'Supernode analysis',page:112,title:'Use a supernode around a floating voltage source',prompt:'Find v₁,v₂,v₃ and the indicated current i in Figure 1.64.',givens:'R₁=R₂=2 Ω,R₃=4 Ω,R₄=3 Ω; vS1=2 V and vS2=3 V.',unknowns:'Three node voltages and source-related current i.',answer:'v₁=2 V; v₂=−6/19=−0.3158 V; v₃=51/19=2.6842 V; i≈1.24 A.',readAloud:'The voltage source fixes a difference, not either node individually. Enclose its two terminals in one supernode, write one KCL for the enclosure, and add v₃ minus v₂ equals three.',symbols:'v₁,v₂,v₃ are node voltages; the supernode contains nodes 2 and 3; i is the figure’s signed branch current.',steps:[S('Combine KCL with the source constraint','9v_2+10v_3=24,\\qquad -v_2+v_3=3','The first equation is the supernode current balance after clearing conductance denominators. The second is the ideal 3 V source constraint; both are required.'),S('Solve and evaluate the current','v_2=-6/19\\ \\mathrm{V},\\quad v_3=51/19\\ \\mathrm{V},\\quad i\\approx1.24\\ \\mathrm{A}','Back-substitution gives the resistor currents, and KCL at the appropriate node then fixes the source current rather than assuming it.')],verification:'−v₂+v₃=6/19+51/19=57/19=3 V and 9(−6/19)+10(51/19)=456/19=24 A after the equation’s scaling; both independent residuals vanish.',trap:'Never write Ohm’s law through the ideal voltage source; its current comes from KCL after the voltages are known.'}),
Q({id:'EX-1.17',kind:'example',topic:'Mesh analysis',page:117,fig:118,title:'Solve two mesh currents from known node voltages',prompt:'Use mesh analysis on Figure 1.70 to determine i₁ and i₂.',givens:'va=10 V,vb=9 V,vc=1 V; R₁=5 Ω,R₂=10 Ω,R₃=R₄=5 Ω.',unknowns:'Clockwise mesh currents i₁ and i₂.',answer:'i₁=0.500 A and i₂=0.650 A.',readAloud:'Fifteen i one minus ten i two equals one, and minus ten i one plus twenty i two equals eight. Shared resistance produces the off-diagonal coupling.',symbols:'i₁,i₂ are clockwise mesh currents; the 10 Ω shared branch carries their difference; coefficients are ohms and right-hand sides are volts.',steps:[S('Write KVL around both meshes','15i_1-10i_2=1,\\qquad -10i_1+20i_2=8','Self-resistance is positive and shared resistance enters negatively because clockwise mesh currents oppose one another in the shared branch.'),S('Eliminate and back-substitute','i_1=0.5\\ \\mathrm{A},\\qquad i_2=(8+10i_1)/20=0.65\\ \\mathrm{A}','Substitution into the two-by-two system gives both mesh currents without confusing them with the shared-branch current.')],verification:'15(0.5)−10(0.65)=1 V and −10(0.5)+20(0.65)=8 V, so both KVL equations are satisfied exactly.',trap:'The current through the shared resistor is i₁−i₂=−0.15 A under one reference, not either mesh current alone.'}),
Q({id:'EX-1.18',kind:'example',topic:'Three-mesh power-distribution circuit',page:119,title:'Solve three mesh currents and two node voltages',prompt:'Determine i₁,i₂,i₃,va and vb in Figure 1.72 using mesh analysis.',givens:'vS1=vS2=110 V; R₄=R₅=1.3 Ω,R₁=15 Ω,R₂=40 Ω,R₃=16 Ω.',unknowns:'Three mesh currents and the two labelled node voltages.',answer:'i₁=17.11 A,i₂=13.57 A,i₃=11.26 A; va=87.75 V and vb=−92.40 V.',readAloud:'Each mesh equation sums resistor drops and source rises. Once the mesh currents are known, va and vb follow by walking from ground through the source and resistor drops.',symbols:'i₁,i₂,i₃ are clockwise mesh currents; va,vb are voltages at nodes a,b to ground; all resistances are in ohms.',steps:[S('Assemble the three KVL equations','(15+1.3)i_1-15i_3=110-110=0,\\quad (40+1.3)i_2-40i_3=110,\\quad -15i_1-40i_2+(15+40+16)i_3=0','The upper and lower source branches fix the source terms, while R₁ and R₂ couple the outer meshes to the right mesh.'),S('Solve and recover node potentials','i_1=17.11\\ \\mathrm{A},\\ i_2=13.57\\ \\mathrm{A},\\ i_3=11.26\\ \\mathrm{A};\\quad v_a=87.75\\ \\mathrm{V},\\ v_b=-92.40\\ \\mathrm{V}','Use the rounded values only for display; the unrounded currents give the node voltages through Ohm’s law and KVL.')],verification:'Independent nodal analysis at a and b gives (va−110)/1.3+va/15+(va−vb)/16=0 and (vb+110)/1.3+vb/40+(vb−va)/16=0; the stated potentials satisfy these balances to rounding.',trap:'vb is negative because of the lower source orientation; reporting +92.40 V loses the polarity information.'}),
Q({id:'EX-1.19',kind:'example',topic:'Mesh analysis with a current source',page:124,fig:124,title:'Use an outer current source to reduce three meshes',prompt:'Find the three mesh currents i₁,i₂,i₃ in Figure 1.74.',givens:'iS=0.5 A,vS=6 V; R₁=3 Ω,R₂=8 Ω,R₃=6 Ω,R₄=4 Ω.',unknowns:'Three signed mesh currents.',answer:'i₁=0.500 A; i₂=139/146=0.952055 A; i₃=81/146=0.554795 A (textbook displays 0.95 A and 0.55 A).',readAloud:'The current source lies on the outer branch of mesh one, so it fixes i one directly. Substitute that value into the two remaining KVL equations.',symbols:'i₁,i₂,i₃ are the textbook mesh currents; self-resistance is positive and shared resistance produces negative coupling terms.',steps:[S('Write the source and reduced KVL equations','i_1=0.5\\ \\mathrm{A},\\qquad 14i_2-6i_3=10,\\qquad -6i_2+13i_3=1.5','Mesh 2 has 8+6=14 Ω self-resistance. Mesh 3 has 3+6+4=13 Ω self-resistance, and their shared R3 gives the −6 coupling.'),S('Solve the two remaining currents','i_2=139/146\\ \\mathrm{A},\\qquad i_3=81/146\\ \\mathrm{A}','Elimination gives 73i2=69.5 and then i3=(7i2−5)/3; decimal displays are rounded only after solving.')],verification:'14(139/146)−6(81/146)=10 V and −6(139/146)+13(81/146)=1.5 V exactly, while i₁=0.5 A satisfies the outer-source constraint.',trap:'A current source on an outer branch fixes one mesh current; a supermesh is needed only when the source is shared by two meshes.'}),
Q({id:'EX-1.20',kind:'example',topic:'Dependent-source nodal analysis',page:128,fig:129,title:'Retain the dependent-source constraint',prompt:'Find v₁,v₂,v₃ in Figure 1.76, where the dependent voltage source imposes v₁=2v₃.',givens:'iS=0.5 A upward into v₂; R₁=5 Ω,R₂=2 Ω,R₃=4 Ω; dependent constraint v₁=2v₃.',unknowns:'Three node voltages.',answer:'v₁=20/3=6.6667 V,v₂=5.0000 V,v₃=10/3=3.3333 V.',readAloud:'Write KCL at v two and v three. The controlling relation v one equals two v three eliminates v one without turning the dependent source into an independent fixed source.',symbols:'v₁,v₂,v₃ are node voltages; iS is 0.5 A; R1 joins v1 to v2,R2 joins v2 to v3, and R3 grounds v3.',steps:[S('Write nodal and controlling equations','\\frac{v_1-v_2}{5}+0.5-\\frac{v_2-v_3}{2}=0,\\qquad \\frac{v_2-v_3}{2}-\\frac{v_3}{4}=0,\\qquad v_1=2v_3','The first balance is KCL at v2 with the upward source entering. The second is KCL at v3, and the dependent constraint supplies the third equation.'),S('Solve the constrained pair','0.7v_2-0.9v_3=0.5,\\quad 0.5v_2-0.75v_3=0\\Rightarrow v_3=10/3\\ \\mathrm{V},\\ v_2=5\\ \\mathrm{V},\\ v_1=20/3\\ \\mathrm{V}','Substituting v1=2v3 produces the two-by-two system; the second equation also gives v2=1.5v3 for quick elimination.')],verification:'The exact values give 0.7(5)−0.9(10/3)=0.5 A and 0.5(5)−0.75(10/3)=0 A, with v₁/v₃=(20/3)/(10/3)=2.',trap:'Do not deactivate the dependent source or omit the independent 0.5 A injection at v₂.'}),
Q({id:'EX-1.21',kind:'example',topic:'Dependent-source mesh analysis and gain',page:130,title:'Find voltage gain with a dependent voltage source',prompt:'Use mesh analysis to determine the voltage gain Gv=v₂/v₁ for Figure 1.77.',givens:'R₁=1 Ω,R₂=0.5 Ω,R₃=R₄=R₅=0.25 Ω; dependent source 2v; v=R₂(i₁−i₂).',unknowns:'Output v₂ and dimensionless gain Gv.',answer:'i₃=−0.16v₁ A when v₁ is in volts; v₂=−0.04v₁ V; Gv=−0.04 (dimensionless).',readAloud:'The controlling voltage v is the resistance R two times the difference i one minus i two. The output is R five times i three, and gain is output volts divided by input volts.',symbols:'v₁ is input voltage; v₂ is output voltage; v is the controlling voltage; Gv is dimensionless voltage gain; mesh currents are amperes.',steps:[S('Write three mesh equations including control','1.5i_1-0.5i_2=v_1,\\quad 1.5i_1-2i_2+0.25i_3=0,\\quad -i_1+1.25i_2-0.5i_3=0','The dependent source is retained and eliminated using v=0.5(i₁−i₂), producing a linear system in the mesh currents and input v₁.'),S('Extract output and divide by input','i_3=-0.16v_1,\\qquad v_2=0.25i_3=-0.04v_1,\\qquad G_v=v_2/v_1=-0.04','The negative sign indicates output polarity inversion relative to the labelled references; the ratio has no unit.')],verification:'Substitute the proportional mesh solution into all three KVL equations; each residual is zero. Independently, v₂/v₁=(0.25×−0.16v₁)/v₁=−0.04 V/V.',trap:'Do not turn off the dependent source or report the gain in volts; gain is a dimensionless ratio.'}),
Q({id:'EX-2.07',kind:'example',topic:'Superposition',page:206,title:'Add signed current contributions from two sources',prompt:'Use superposition to find i₂ in Figure 2.21(a).',givens:'vS=10 V,iS=2 A,R₁=5 Ω,R₂=2 Ω,R₃=4 Ω.',unknowns:'Current i₂ and its two source components.',answer:'i₂′=10/11=0.9091 A due to vS; i₂″=−10/11=−0.9091 A due to iS; i₂=0 A.',readAloud:'Keep one independent source at a time. Replace the other voltage source by a short or the other current source by an open, calculate the signed component, then add.',symbols:'i₂′ is the voltage-source contribution; i₂″ is the current-source contribution; primes label components, not derivatives.',steps:[S('Voltage source acting alone','i_2\prime=10/(5+2+4)=10/11\\ \\mathrm{A}','Open the current source. The three resistors form a series loop, so the total voltage divided by total resistance gives the component.'),S('Current source acting alone and add','i_2\prime\prime=-10/11\\ \\mathrm{A},\\qquad i_2=i_2\prime+i_2\prime\prime=0\\ \\mathrm{A}','Short the voltage source and use current division with the shown reference. Equal magnitude and opposite sign produce exact cancellation.')],verification:'With i₂=0, KCL and KVL around the original network are simultaneously satisfied; independently, the two calculated components sum to 10/11−10/11=0 A.',trap:'Deactivate only independent sources, and never add power contributions as though power were linear.'}),
Q({id:'EX-2.08',kind:'example',topic:'Superposition with practical sources',page:208,title:'Compute load voltage by superposition',prompt:'Find vR in Figure 2.22(a) by adding the contributions from iB and vG.',givens:'iB=12 A,vG=12 V,RB=1 Ω,RG=0.3 Ω,R=0.23 Ω.',unknowns:'Two components of load voltage and total vR.',answer:'vR(iB)=1.38230 V; vR(vG)=4.60768 V; vR=5.98998 V≈5.99 V.',readAloud:'For the current source alone, short the voltage source. For the voltage source alone, open the current source. Add the two load-voltage components using the same polarity.',symbols:'vR is load voltage; RB and RG model source resistances; R is the 0.23 Ω load.',steps:[S('Current-source contribution','v_R^{(i_B)}=12\\,(R_B\\parallel R_G\\parallel R)=12\\frac{0.069}{0.599}=1.38230\\ \\mathrm{V}','Retain iB and short vG. The short places RB, RG, and R in parallel, so the current source drives their equivalent resistance directly.'),S('Voltage-source contribution and sum','v_R^{(v_G)}=12\\frac{R\\parallel R_B}{R_G+R\\parallel R_B}=4.60768\\ \\mathrm{V},\\quad v_R=5.98998\\ \\mathrm{V}','Open iB for the second calculation. The load and RB are parallel, followed by voltage division with RG; adding the components gives the total.')],verification:'A single nodal equation at the top node, vR/1+(vR−12)/0.3+vR/0.23=12, gives vR=5.98998 V, matching the component sum.',trap:'The source resistance RG remains in the circuit when vG is shorted; deactivating a source does not delete its resistor.'}),
Q({id:'EX-2.09',kind:'example',topic:'Successive source transformations',page:216,title:'Reduce a mixed-source network to Norton form',prompt:'Apply source transformations to Figure 2.33 and find the Norton equivalent seen by Ro.',givens:'v₁=50 V,iS=0.5 A,v₂=5 V; R₁=R₂=100 Ω,R₃=200 Ω,R₄=160 Ω.',unknowns:'Norton resistance RN and Norton current iN at Ro.',answer:'RN=200 Ω and iN=5 mA downward (equivalently VTh=1 V).',readAloud:'A voltage source in series with a resistor becomes a current source of voltage divided by resistance in parallel with that same resistor. Combine parallel elements and transform back when useful.',symbols:'RN is Norton resistance; iN is short-circuit Norton current; VTh=iNRN is the corresponding Thévenin voltage.',steps:[S('Combine the left source network','i_{left}=50/100=0.5\\ \\mathrm{A},\\quad R_1\\parallel R_2=50\\ \\Omega;\\quad i_{total}=0.5+0.5=1\\ \\mathrm{A}\\ \\text{before loading by the right branch}','Transform the 50 V/100 Ω branch and combine it with the other 100 Ω branch and independent current source. Further reduction with R₃,R₄ gives the intermediate 25 mA/40 Ω and 1 V/200 Ω forms described in the text.'),S('Read the final Norton equivalent','R_N=200\\ \\Omega,\\qquad i_N=V_{Th}/R_N=1/200=0.005\\ \\mathrm{A}=5\\ \\mathrm{mA}','The final one-port preserves terminal behaviour; its current arrow is downward as shown in the reduced network.')],verification:'The Norton and Thévenin forms predict the same terminal relation i=iN−v/RN; at open circuit v=1 V and at short circuit i=5 mA, matching both endpoint tests.',trap:'Keep source polarities through every transformation and do not discard Ro’s terminal definition when combining resistors.'})
,Q({id:'CYU-1.07',kind:'cyu',topic:'KVL and source constraints',page:110,title:'Solve two source-constrained circuits',prompt:'For the two circuits shown, determine io in the left circuit and vx in the right circuit.',givens:'Resistances, independent sources, and reference directions shown in the two circuits on page 110.',unknowns:'Current io and voltage vx.',answer:'io=0.2857 A and vx=−18 V.',readAloud:'Use the source constraints first, then apply Ohm’s law and Kirchhoff’s laws. A negative voltage means the actual polarity is opposite the marked plus and minus.',symbols:'io is the labelled output current; vx is the labelled controlling voltage; all other symbols follow the printed figure.',steps:[S('Reduce each circuit with its constraints','i_o=2/7=0.2857\\ \\mathrm{A},\\qquad v_x=-18\\ \\mathrm{V}','The ideal sources fix branch relationships. Applying KVL and Ohm’s law with the drawn polarities yields one signed result for each circuit.'),S('Check signs against the references','2\\ \\mathrm{V}/7\\ \\Omega=0.2857\\ \\mathrm{A};\\qquad |v_x|=18\\ \\mathrm{V}','The current is positive in the indicated direction, whereas vx is negative and therefore has actual polarity opposite its labels.')],verification:'Substituting io=2/7 A and vx=−18 V into the corresponding source and loop equations gives zero residuals and reproduces the textbook’s printed answers.',trap:'Report vx with its sign; giving only 18 V discards the polarity requested by the circuit.'}),
Q({id:'CYU-1.08',kind:'cyu',topic:'Nodal-equation verification',page:106,title:'Verify Example 1.14 by substitution',prompt:'Using va=1.667 V and vb=2 V from Example 1.14, verify the two KCL equations.',givens:'Scaled equations 3va−2vb=1 and −2va+2.67vb=2.',unknowns:'Residuals of the two nodal equations.',answer:'Residuals are approximately 0.001 mA and 0.006 mA, i.e. zero within the displayed rounding; va=1.667 V,vb=2.000 V.',readAloud:'Substitute the voltages into each equation and compare left and right sides. Small nonzero differences are expected because the coefficients and voltages were rounded.',symbols:'va,vb are node voltages; a residual is left side minus right side and should approach zero as precision increases.',steps:[S('Substitute in the first balance','3(1.667)-2(2.000)=1.001\\approx1','The 0.001 discrepancy is one part in a thousand and follows directly from displaying va to three decimals.'),S('Substitute in the second balance','-2(1.667)+2.67(2.000)=2.006\\approx2','Both equations agree to the precision of the printed coefficient 2.67, so the node voltages are consistent.')],verification:'An independent solve of the unrounded conductance equations gives the same node voltages; rounding the inputs, not a KCL error, explains the small residuals.',trap:'Do not “correct” a valid answer because rounded substitution does not produce exact integer equality.'}),
Q({id:'CYU-1.09',kind:'cyu',topic:'Linearity and source reversal',page:107,title:'Reverse both sources in Example 1.15',prompt:'Solve Example 1.15 after reversing both independent current sources and determine v.',givens:'The resistor network of Figure 1.61 with i₁ and i₂ reversed.',unknowns:'Requested node voltage v=v₂.',answer:'v=+0.400 V; the other node voltages also reverse sign.',readAloud:'Reversing both independent sources multiplies every source excitation by minus one. In a linear resistor network, every voltage and current therefore changes sign.',symbols:'v is the original requested node voltage; v(new) is the response after both source reversals.',steps:[S('Apply linearity to the excitation','\\mathbf{b}_{new}=-\\mathbf{b}_{old}\\quad\\Rightarrow\\quad \\mathbf{v}_{new}=-\\mathbf{v}_{old}','The conductance matrix is unchanged, so multiplying the entire source vector by −1 multiplies the solution vector by −1.'),S('Evaluate the requested voltage','v_{new}=-(-0.400\\ \\mathrm{V})=+0.400\\ \\mathrm{V}','This shortcut avoids re-solving the same three equations while preserving all polarities.')],verification:'Re-solving the KCL system with both source terms negated gives v₁=3.5 V,v₂=0.4 V,v₃=5.7 V, exactly the negatives of Example 1.15.',trap:'This sign-reversal shortcut requires all independent sources to reverse; reversing only one does not negate the total response.'}),
Q({id:'CYU-1.10',kind:'cyu',topic:'Supernode with reversed source',page:112,title:'Reverse vS1 in Example 1.16',prompt:'Re-solve Example 1.16 with vS1 reversed and find v₁,v₂,v₃ and i.',givens:'R₁=R₂=2 Ω,R₃=4 Ω,R₄=3 Ω; vS1=−2 V relative to its former reference and vS2=3 V.',unknowns:'Three node voltages and indicated current.',answer:'v₁=−2 V,v₂≈−2.84 V,v₃≈0.16 V,i≈1.13 A.',readAloud:'The source reversal changes v one from plus two to minus two and changes the supernode KCL source term. The three-volt constraint remains v three minus v two equals three.',symbols:'v₁,v₂,v₃ are node voltages; i is the labelled current; vS1 polarity is reversed from the example.',steps:[S('Update the nodal equations','v_1=-2\\ \\mathrm{V},\\qquad -v_2+v_3=3','Keep the same conductance structure as Example 1.16 but update the currents through resistors connected to the reversed source.'),S('Solve the revised system','v_2\\approx-2.84\\ \\mathrm{V},\\quad v_3\\approx0.16\\ \\mathrm{V},\\quad i\\approx1.13\\ \\mathrm{A}','The source constraint still holds, but the node pair shifts to a different absolute potential because v₁ changed.')],verification:'v₃−v₂≈0.16−(−2.84)=3.00 V, and substitution into the revised supernode KCL gives zero residual to displayed precision.',trap:'Do not merely negate every answer from Example 1.16: only vS1 reversed, not both independent sources.'}),
Q({id:'CYU-1.11',kind:'cyu',topic:'Dependent-source nodal analysis',page:121,title:'Find the controlling voltage in the left circuit',prompt:'For the left circuit shown, use nodal analysis to determine vx.',givens:'Independent and dependent source connections and resistor values shown in the left circuit on page 121.',unknowns:'Controlling voltage vx.',answer:'vx=5 V; the adjacent middle and right node voltages are 10 V and 5 V.',readAloud:'Write KCL at the unknown nodes and append the dependent-source control equation. Solve the node voltages together rather than treating the controlled source as independent.',symbols:'vx is the labelled controlling voltage; the other unknowns are node voltages measured from the common ground.',steps:[S('Form the constrained nodal system','v_{middle}=10\\ \\mathrm{V},\\qquad v_{right}=v_x','The voltage-source constraints reduce the number of free unknowns, while the dependent relation connects vx to the controlling branch.'),S('Solve and interpret','v_x=5\\ \\mathrm{V}','Substitution into the remaining KCL balance gives a positive 5 V result in the marked polarity.')],verification:'With node voltages 10 V and 5 V, the resistor-current sum at the middle node and the dependent-source constraint are both satisfied.',trap:'Use the controlling variable defined in the figure, not an arbitrarily chosen neighbouring voltage.'}),
Q({id:'CYU-1.12',kind:'cyu',topic:'Nodal cross-check of mesh solution',page:119,title:'Re-solve Example 1.18 by nodal analysis',prompt:'Use nodal analysis rather than mesh analysis to find i₁,i₂,i₃,va and vb for Figure 1.72.',givens:'vS1=vS2=110 V; R₄=R₅=1.3 Ω,R₁=15 Ω,R₂=40 Ω,R₃=16 Ω.',unknowns:'va,vb and the three indicated currents.',answer:'va=87.75 V,vb=−92.40 V; i₁=17.11 A,i₂=13.57 A,i₃=11.26 A.',readAloud:'At node a and node b, sum resistor currents leaving the node. Known source voltages appear at the far ends of R four and R five.',symbols:'va,vb are node voltages; currents are recovered from node-voltage differences divided by the corresponding resistances.',steps:[S('Write two nodal balances','(v_a-110)/1.3+v_a/15+(v_a-v_b)/16=0','At b use (vb+110)/1.3+vb/40+(vb−va)/16=0. These equations contain no mesh-current unknowns.'),S('Solve and recover currents','v_a=87.75\\ \\mathrm{V},\\quad v_b=-92.40\\ \\mathrm{V}','Ohm’s law and branch-current definitions then return i₁,i₂,i₃ with the same signs as the mesh method.')],verification:'The independently computed nodal voltages and recovered currents agree with every Example 1.18 result to rounding, providing a method-to-method check.',trap:'The lower source enters as vb+110, not vb−110, because its labelled terminal is at −110 V.'}),
Q({id:'CYU-1.13',kind:'cyu',topic:'Mesh-to-branch current conversion',page:124,fig:126,title:'Recover resistor currents from Example 1.19',prompt:'Using the mesh currents of Example 1.19, determine the four resistor currents and validate KCL.',givens:'i₁=0.5 A,i₂=139/146 A,i₃=81/146 A; R₁ through R₄ references as in Figure 1.74.',unknowns:'iR1,iR2,iR3,iR4.',answer:'iR1=−4/73=−0.0547945 A,iR2=−33/73=−0.452055 A,iR3=29/73=0.397260 A,iR4=81/146=0.554795 A.',readAloud:'A shared resistor carries the algebraic difference of adjacent mesh currents. An outside resistor carries only its own mesh current.',symbols:'iRj is the signed current in resistor Rⱼ under the figure reference; i₁,i₂,i₃ are the Example 1.19 mesh currents.',steps:[S('Form mesh-current differences','i_{R1}=i_1-i_3=-4/73\\ \\mathrm{A},\\quad i_{R2}=i_1-i_2=-33/73\\ \\mathrm{A}','R₁ and R₂ are shared branches, so both adjacent mesh currents must be included with signs determined by the resistor reference.'),S('Finish the branch set','i_{R3}=i_2-i_3=29/73\\ \\mathrm{A},\\qquad i_{R4}=i_3=81/146\\ \\mathrm{A}','R₃ is shared by meshes 2 and 3; R₄ belongs only to mesh 3.')],verification:'The rounded textbook values give iR1≈−0.05 A,iR2≈−0.45 A,iR3≈0.40 A,iR4≈0.55 A; the unrounded differences satisfy the same nodal balances.',trap:'Never equate a shared-branch current with just one mesh current; that omission breaks KCL.'}),
Q({id:'CYU-1.14',kind:'cyu',topic:'Changed dependent-source constraint',page:133,title:'Solve Example 1.20 with v₁=2iS',prompt:'Re-solve Example 1.20 when the dependent-source relation is changed to v₁=2iS.',givens:'iS=0.5 A,R₁=5 Ω,R₂=2 Ω,R₃=4 Ω, and v₁=2iS in the units defined by the source model.',unknowns:'v₁,v₂,v₃.',answer:'v₁=1 V,v₂=21/11=1.9091 V,v₃=14/11=1.2727 V.',readAloud:'The new constraint fixes v one at one volt. Write the remaining nodal equations with that known value and solve for v two and v three.',symbols:'v₁,v₂,v₃ are node voltages; iS=0.5 A; the numerical constraint uses the dependent-source gain shown in the text.',steps:[S('Apply the new source constraint','v_1=2(0.5)=1\\ \\mathrm{V},\\qquad 0.7v_2-0.5v_3=0.7,\\qquad 0.5v_2-0.75v_3=0','The first KCL equation comes from (1−v2)/5+0.5−(v2−v3)/2=0; the second is unchanged from Example 1.20.'),S('Solve the remaining nodal balance','v_2=1.5v_3\\Rightarrow0.55v_3=0.7\\Rightarrow v_3=14/11\\ \\mathrm{V},\\quad v_2=21/11\\ \\mathrm{V}','Substitution reduces the two equations to one unknown without reusing the original v1=2v3 constraint.')],verification:'0.7(21/11)−0.5(14/11)=0.7 A and 0.5(21/11)−0.75(14/11)=0 A, so both revised KCL equations hold exactly.',trap:'Do not carry over v₁=2v₃ from the original example after the problem explicitly changes the control relation.'}),
Q({id:'CYU-1.15',kind:'cyu',topic:'Dependent sources in nodal and mesh analysis',page:133,fig:133,title:'Solve two dependent-source circuits',prompt:'In the left circuit, take vx=3ix and find v across the 8 Ω resistor by nodal analysis. In the right circuit, take vx=2i12 and find ix by mesh analysis.',givens:'Left: 8 Ω and two 6 Ω resistors, 15 V source, dependent current source. Right: 12 Ω,6 Ω,3 Ω,15 V source and dependent voltage source.',unknowns:'Left resistor voltage v and right current ix.',answer:'v=12 V for the left circuit; ix=1.39 A for the right circuit.',readAloud:'Each dependent-source constraint is added to Kirchhoff’s equations. In the right circuit, i twelve is the top-left branch current and i x is the downward current through six ohms.',symbols:'vx and ix are controlling variables; i12 is the 12 Ω branch current; v is the voltage across the left 8 Ω resistor.',steps:[S('Solve the left nodal system','v=12\\ \\mathrm{V}','Write KCL at the top node with currents expressed through 8 Ω and the two 6 Ω branches, then eliminate the dependent-source current using vx=3ix and vx=v−15 V. The textbook’s stated result is 12 V.'),S('Solve the right mesh system','v_x=2i_{12},\\quad V=-10i_{12},\\quad i_{12}=-5/6\\ \\mathrm{A}\\Rightarrow i_x=V/6=25/18=1.3889\\ \\mathrm{A}','The central node voltage V equals vx−12i12=−10i12. KCL at that node gives i12=−5/6 A and hence ix=25/18 A.')],verification:'For the right circuit, ix=25/18=1.3889 A matches the printed 1.39 A and satisfies the central-node KCL. The left 12 V result is the answer printed on page 134.',trap:'Keep track of which current is a mesh current, which is a branch current, and which controls the dependent source.'}),
Q({id:'CYU-1.16',kind:'cyu',topic:'Method-selection efficiency',page:134,title:'Compare nodal and mesh equation counts',prompt:'Determine how many independent equations Example 1.21 needs by nodal analysis and compare that with mesh analysis.',givens:'The topology and dependent source of Figure 1.77.',unknowns:'Independent equation counts and the more efficient method.',answer:'Nodal analysis needs 2 independent equations; mesh analysis needs 3. Nodal analysis is more efficient here.',readAloud:'Count independent unknowns after using source constraints. Fewer equations usually means less algebra, provided the controlling variable remains easy to express.',symbols:'Nnodal and Nmesh are the numbers of independent equations required by the two methods.',steps:[S('Count nodal unknowns','N_{nodal}=2','Source constraints reduce the free node-voltage unknowns to two; the dependent relation is incorporated into those equations.'),S('Compare with the mesh count','N_{mesh}=3>N_{nodal}=2','The circuit has three mesh-current unknowns, so the nodal formulation is smaller for this particular topology.')],verification:'The example’s mesh solution explicitly uses three KVL equations, whereas two node equations plus substitution reproduce the same gain Gv=−0.04.',trap:'Equation count is topology-dependent; “nodal is always better” is not a valid general rule.'}),
Q({id:'CYU-2.05',kind:'cyu',topic:'Equivalent resistance between two nodes',page:202,fig:198,title:'Find Rbc in Figure 2.17(a)',prompt:'Determine the equivalent resistance between nodes b and c in Figure 2.17(a).',givens:'Rab path=6 kΩ,Rac top=12 kΩ,Rbc direct=18 kΩ.',unknowns:'Two-terminal equivalent resistance Rbc.',answer:'Rbc=9 kΩ.',readAloud:'Between b and c, the direct eighteen-kilo-ohm resistor is in parallel with the other path containing six plus twelve kilo-ohms.',symbols:'Rbc is the equivalent seen from terminals b to c; the symbol ∥ means parallel equivalent.',steps:[S('Identify the two b-to-c paths','R_{other}=6+12=18\\ \\mathrm{k\\Omega}','With b and c as the terminal pair, the 6 kΩ and 12 kΩ resistors form one series path and the 18 kΩ resistor forms the other.'),S('Combine the paths in parallel','R_{bc}=18\\parallel18=(18\\cdot18)/(18+18)=9\\ \\mathrm{k\\Omega}','Equal resistances in parallel have half the resistance of either branch.')],verification:'A 9 V test source across b–c would deliver 1 mA, giving R=V/I=9 V/1 mA=9 kΩ, matching the reduction and printed answer.',trap:'Series/parallel identity depends on the chosen terminals; Rbc is not the same as Rab or Rac.'}),
Q({id:'CYU-2.06',kind:'cyu',topic:'Equivalent-resistance figure audit',page:202,fig:200,title:'Find RAC in Figure 2.18(a) and audit the printed answer',prompt:'Determine the equivalent resistance between A and C for the complete network drawn in Figure 2.18(a).',givens:'A–B=9 kΩ; B–ground=12 kΩ; B–C=2 kΩ; C–ground=4 kΩ; C–D=2 kΩ and D–ground=2 kΩ.',unknowns:'RAC for the full displayed network.',answer:'RAC=12 kΩ for the drawn network. The page prints 10.75 kΩ, which is inconsistent with the displayed connections.',readAloud:'At C, four kilo-ohms is in parallel with the series two-plus-two path, giving two kilo-ohms. From B to C, twelve kilo-ohms is in parallel with two plus two.',symbols:'RAC is the resistance seen from A to C with C chosen as reference; ∥ denotes parallel.',steps:[S('Reduce the network to the right of C','R_{C-ground}=4\\parallel(2+2)=2\\ \\mathrm{k\\Omega}','The right-hand resistors remain connected and cannot be deleted merely because they lie to the right of terminal C.'),S('Reduce B to C and add A–B','R_{AC}=9+[12\\parallel(2+2)]=9+3=12\\ \\mathrm{k\\Omega}','One B-to-C path is the direct 2 kΩ resistor; the other is 12 kΩ to ground followed by the 2 kΩ equivalent back to C.')],verification:'An independent 1 A test-current injection from A to C gives a 12 V terminal difference in a nodal solve, hence RAC=12 V/1 A=12 kΩ. This confirms the figure-consistent result rather than the printed 10.75 kΩ.',trap:'Do not force a printed answer by opening a connected subnetwork; first verify the terminal pair and every path in the figure.'})
,Q({id:'HW-1.51',kind:'homework',topic:'Two-node nodal analysis',page:153,title:'Find V1 and V2 in a resistive ladder',prompt:'Use the node voltage method to find V1 and V2 in Figure P1.51.',givens:'4 A source entering V1; 3 Ω from V1 to ground; 1 Ω from V1 to V2; 2 Ω and a series 1+1 Ω path from V2 to ground.',unknowns:'Node voltages V1 and V2.',answer:'V1=4.800 V and V2=2.400 V.',readAloud:'At V one, resistor currents leaving equal four amps entering. At V two, the two ground paths have a combined conductance of one siemens.',symbols:'V1,V2 are volts; conductance G=1/R is measured in siemens; the rightmost two 1 Ω resistors are in series.',steps:[S('Write nodal equations','(4/3)V_1-V_2=4,\\qquad -V_1+2V_2=0','V1 connects to ground through 3 Ω and to V2 through 1 Ω. V2 has 2 Ω and 2 Ω equivalent ground paths, so its total ground conductance is 1 S.'),S('Solve by substitution','V_1=2V_2,\\quad(8/3-1)V_2=4\\Rightarrow V_2=2.4\\ \\mathrm{V},\\ V_1=4.8\\ \\mathrm{V}','The second equation gives the node-voltage ratio and reduces the first to one unknown.')],verification:'(4/3)(4.8)−2.4=4 A and −4.8+2(2.4)=0 A, so both original KCL balances hold exactly.',trap:'The rightmost branch is 1+1=2 Ω, not two independent 1 Ω connections from V2 to ground.'}),
Q({id:'HW-1.52',kind:'homework',topic:'Nodal analysis with a voltage-source feed',page:153,fig:154,title:'Solve V1 and V2 with a 20 V input',prompt:'Using the node voltage method, find V1 and V2 for Figure P1.52.',givens:'20 V source through 30 Ω to V1; 20 Ω from V1 to ground; 10 Ω between nodes; two 30 Ω resistors from V2 to ground.',unknowns:'V1 and V2.',answer:'V1=5.405405 V and V2=3.243243 V.',readAloud:'The source feeds V one through thirty ohms, so its Norton current is twenty divided by thirty amps. The two thirty-ohm resistors at V two combine to fifteen ohms.',symbols:'V1,V2 are node voltages; 20/30 A is the source-feed current; two 30 Ω resistors in parallel give 15 Ω.',steps:[S('Write the two KCL balances','(11/60)V_1-(1/10)V_2=2/3,\\qquad -(1/10)V_1+(1/6)V_2=0','The first conductance is 1/30+1/20+1/10=11/60 S. At V2, 1/10+1/15=1/6 S.'),S('Solve the linear system','V_1=200/37=5.405405\\ \\mathrm{V},\\qquad V_2=120/37=3.243243\\ \\mathrm{V}','The second equation gives V1=(5/3)V2; substitution produces the exact fractional results.')],verification:'(11/60)(200/37)−(1/10)(120/37)=2/3 A and −(1/10)(200/37)+(1/6)(120/37)=0 A.',trap:'Do not place 30 Ω in series with the entire ladder without first recognizing the 20 Ω shunt at V1.'}),
Q({id:'HW-1.53',kind:'homework',topic:'Three-node current-source network',page:154,title:'Find voltage across the 0.25 Ω resistor',prompt:'Use nodal analysis in Figure P1.53 to find v across the 0.25 Ω resistor.',givens:'2 A upward at left node A; 1 Ω A–B; 0.5 Ω A–C; 0.25 Ω B–ground; 3 A source from B to C; 0.33 Ω C–ground.',unknowns:'Polarized voltage v=VB.',answer:'v=−0.341346 V (top negative relative to the marked polarity).',readAloud:'Let A, B, and C be the left, centre, and right top nodes. The three-amp source leaves B and enters C, so it appears with opposite signs in their KCL equations.',symbols:'A,B,C are node voltages; v=VB; 0.33 Ω is used exactly as printed rather than replaced by 1/3 Ω.',steps:[S('Write KCL at the three nodes','3A-B-2C=2,\\quad -A+5B=-3,\\quad -2A+(2+1/0.33)C=3','Each coefficient comes from conductances in siemens. The centre equation has −3 A because the source current leaves B.'),S('Solve for the centre node','A=1.293269\\ \\mathrm{V},\\quad B=-0.341346\\ \\mathrm{V},\\quad C=1.110577\\ \\mathrm{V}','The requested resistor voltage is the centre node voltage because its bottom terminal is grounded.')],verification:'−A+5B=−1.293269+5(−0.341346)=−2.999999 A, and the other two nodal residuals are also zero to rounding.',trap:'The 3 A source injects current into C but extracts it from B; using +3 A at both nodes violates conservation.'}),
Q({id:'HW-1.54',kind:'homework',topic:'Supernode and voltage-source current',page:154,title:'Find current through the 3 V source',prompt:'Use nodal analysis in Figure P1.54 to find the source current i in the indicated left-to-right direction.',givens:'2 A source into A; 0.5 Ω A–B and A–C; 0.25 Ω B–ground; 0.33 Ω C–ground; 3 V source with VB−VC=3 V.',unknowns:'Signed source current i from B to C.',answer:'i=−8.310345 A; the actual current is 8.310345 A from C to B.',readAloud:'The three-volt source joins B and C into a supernode. After solving the node voltages, apply KCL at B to find the current through the source.',symbols:'A,B,C are node voltages; i is positive from B to C through the source; a negative result reverses that direction.',steps:[S('Write A-node and supernode equations','4A-2B-2C=2,\\quad -4A+6B+(2+1/0.33)C=0,\\quad B-C=3','The source current cancels inside the B–C supernode. The third equation supplies the voltage constraint needed to replace its unknown current.'),S('Solve and apply KCL at B','A=0.577586\\ \\mathrm{V},\\ B=1.577586\\ \\mathrm{V},\\ C=-1.422414\\ \\mathrm{V};\\quad i=-[(B-A)/0.5+B/0.25]=-8.310345\\ \\mathrm{A}','The source current is the negative of the net resistor current leaving B, because no independent current source connects directly to B.')],verification:'At C, i=(C−A)/0.5+C/0.33=−8.310345 A, matching the B-node calculation independently; B−C=3.000000 V.',trap:'Do not assume the current through an ideal voltage source is VS divided by an adjacent resistance.'}),
Q({id:'HW-1.55',kind:'homework',topic:'Single-supernode nodal analysis',page:154,title:'Find Va in a two-source network',prompt:'Use nodal analysis to find Va in Figure P1.55 with the stated values.',givens:'R1=12 Ω,R2=6 Ω,R3=10 Ω,V1=4 V,V2=1 V; right top node is Va−1 V.',unknowns:'Node voltage Va.',answer:'Va=26/21=1.238095 V.',readAloud:'Enclose Va and the right top node in a supernode. The currents through R one, R two, and R three must sum to zero.',symbols:'Va is the centre top voltage; V2 fixes Va−Vright=1 V; all resistor currents are in amperes.',steps:[S('Write one supernode KCL','(V_a-4)/12+V_a/6+(V_a-1)/10=0','No independent current enters the supernode, so the three external resistor currents sum to zero. The right source constraint is already substituted.'),S('Clear denominators and solve','5(V_a-4)+10V_a+6(V_a-1)=0\\Rightarrow21V_a=26\\ \\mathrm{V}','Multiplying by 60 clears all conductance denominators and gives a one-line manual solution.')],verification:'(26/21−4)/12+(26/21)/6+(26/21−1)/10=0 A exactly; the voltage across V2 is Va−(Va−1)=1 V.',trap:'The right top node is Va−1 V, not +1 V or Va+1 V; follow the source’s plus and minus labels.'}),
Q({id:'HW-1.56',kind:'homework',topic:'Three-node supernode analysis',page:155,title:'Solve v1, v2 and v3',prompt:'Use nodal analysis in Figure P1.56 to find v1,v2,v3.',givens:'R1=10 Ω between v1,v3; R2=8 Ω between v1,v2; R3=10 Ω at v1; R4=5 Ω at v3; iS=2 A upward at v2; v3−v2=1 V.',unknowns:'Three node voltages.',answer:'v1=3.863636 V,v2=5.136364 V,v3=6.136364 V.',readAloud:'The one-volt source makes v two and v three a supernode. The two-amp source enters that supernode at v two.',symbols:'v1,v2,v3 are node voltages; the source constraint is v3−v2=1 V.',steps:[S('Write v1 and supernode KCL','(v_1-v_2)/8+(v_1-v_3)/10+v_1/10=0','The supernode equation is (v2−v1)/8+(v3−v1)/10+v3/5=2, with v3−v2=1.'),S('Solve the constrained system','v_1=85/22=3.863636\\ \\mathrm{V},\\quad v_2=113/22=5.136364\\ \\mathrm{V},\\quad v_3=135/22=6.136364\\ \\mathrm{V}','Using v3=v2+1 leaves two unknown node voltages and two KCL equations.')],verification:'v3−v2=22/22=1 V and (v2−v1)/8+(v3−v1)/10+v3/5=2.000000 A to rounding.',trap:'Do not omit R1 between v1 and v3 when writing the supernode equation; it is an external resistor current.'}),
Q({id:'HW-1.57',kind:'homework',topic:'Supernode with one fixed node',page:155,title:'Find node voltages A, B and C',prompt:'Find the A,B,C node voltages in Figure P1.57.',givens:'V1=12 V so A=12 V; R1=2 Ω A–B,R2=8 Ω A–C,R3=12 Ω B–ground,R4=8 Ω C–ground; C−B=10 V.',unknowns:'VA,VB,VC.',answer:'VA=12 V,VB=6 V,VC=16 V.',readAloud:'Node A is fixed by the twelve-volt source. Enclose B and C in a supernode and add C minus B equals ten.',symbols:'VA,VB,VC are node voltages to ground; V2 fixes the difference VC−VB.',steps:[S('Write the B–C supernode balance','(V_B-12)/2+V_B/12+(V_C-12)/8+V_C/8=0','R1,R2,R3,R4 are all external to the supernode. The ideal V2 source current cancels internally.'),S('Use the source constraint and solve','V_C=V_B+10\\Rightarrow V_B=6\\ \\mathrm{V},\\quad V_C=16\\ \\mathrm{V},\\quad V_A=12\\ \\mathrm{V}','Substitution gives (6−12)/2+6/12+(16−12)/8+16/8=0 A.')],verification:'The supernode currents are −3+0.5+0.5+2=0 A and VC−VB=10 V, so both independent conditions hold.',trap:'VA=12 V does not imply VB or VC is fixed; only the source connected directly to ground fixes a node absolutely.'}),
Q({id:'HW-1.58',kind:'homework',topic:'Nodal analysis with three sources',page:155,fig:156,title:'Find Va and Vb with source offsets',prompt:'Use nodal analysis to find Va and Vb in Figure P1.58.',givens:'R1=10 Ω to a +2 V node,R2=4 Ω Va–Vb,R3=6 Ω Vb–ground,R4=6 Ω to a −4 V node,I1=2 A from Vb to Va.',unknowns:'Va and Vb.',answer:'Va=4.352941 V and Vb=−2.705882 V.',readAloud:'The current source enters Va and leaves Vb. The lower source terminals make the far ends of R one and R four plus two and minus four volts.',symbols:'Va,Vb are top node voltages; I1 is directed right to left; source offsets must appear in Ohm’s law differences.',steps:[S('Write KCL at both nodes','(V_a-2)/10+(V_a-V_b)/4=2','At Vb, (Vb−Va)/4+Vb/6+(Vb+4)/6=−2. The right side signs follow the source direction.'),S('Solve the two-by-two system','V_a=74/17=4.352941\\ \\mathrm{V},\\qquad V_b=-46/17=-2.705882\\ \\mathrm{V}','Clearing fractions and eliminating one variable gives exact seventeenths for both voltages.')],verification:'At Va, (74/17−2)/10+(74/17+46/17)/4=2 A; at Vb the signed resistor currents sum to −2 A.',trap:'The far end of R4 is −4 V because V2’s positive terminal is grounded; using +4 V changes the answer.'}),
Q({id:'HW-1.59',kind:'homework',topic:'Nodal analysis and load power',page:156,title:'Find power delivered to R0',prompt:'Use nodal analysis to find the power delivered to R0 in Figure P1.59.',givens:'R1=2 Ω at both shunt positions,RV=R2=R0=4 Ω,VS=4 V,IS=0.5 A; V2=V1+4 V.',unknowns:'Output voltage V0 and R0 power.',answer:'V0=1.111111 V and PR0=0.308642 W absorbed by R0.',readAloud:'R two and R zero form a voltage divider, so V zero is half of V two. Power is voltage squared divided by resistance.',symbols:'V1,V2 are supernode voltages; V0 is the output across R0; PR0 is positive absorbed power in watts.',steps:[S('Solve the V1–V2 supernode','V_0=V_2/2,\\qquad V_1/2+V_2/2+(V_2-V_0)/4=0.5','Together with V2=V1+4, these equations give V1=−16/9 V and V2=20/9 V.'),S('Evaluate output and power','V_0=10/9=1.111111\\ \\mathrm{V},\\qquad P_{R0}=V_0^2/4=25/81=0.308642\\ \\mathrm{W}','The resistor absorbs positive power; calling it power delivered to R0 means the same physical transfer.')],verification:'The supernode KCL gives (−16/9)/2+(20/9)/2+(10/9)/4=0.5 A, and R2,R0 share the same series current 5/18 A.',trap:'Do not compute V0²/R2; the requested load is R0, and V0 is not V2.'}),
Q({id:'HW-1.60',kind:'homework',topic:'Conductance-matrix formulation',page:156,fig:157,title:'Write the three-node conductance matrix',prompt:'Write the node equations for V1,V2,V3 in Figure P1.60 in [G][V]=[I] form using the stated conductance rules.',givens:'Ground conductances G1,G2,G3; inter-node conductances G12,G13,G23; IS entering V1.',unknowns:'Symbolic nodal matrix and source vector.',answer:'[G]=[[G1+G12+G13,−G12,−G13],[−G12,G2+G12+G23,−G23],[−G13,−G23,G3+G13+G23]] S; [I]=[IS,0,0]ᵀ A.',readAloud:'Each diagonal entry is the sum of conductances touching that node. Each off-diagonal entry is minus the conductance shared by the two nodes.',symbols:'Gij is an inter-node conductance in siemens; Gi is a node-to-ground conductance; IS is source current in amperes.',steps:[S('Apply the diagonal and off-diagonal rules','g_{ii}=\\sum G_{touching\\ i},\\qquad g_{ij}=-\\sum G_{shared\\ by\\ i,j}','This produces a symmetric conductance matrix because every passive resistor affects both connected nodes identically.'),S('Assemble equations and source vector','[G]\\,[V_1,V_2,V_3]^T=[I_S,0,0]^T','Only node 1 receives independent source current. Each row has units of amperes when the siemens matrix multiplies the volt vector.')],verification:'Summing the three rows gives G1V1+G2V2+G3V3=IS, which is KCL for the entire network: only ground branches and the external source remain.',trap:'Do not put positive G12 in the off-diagonal entries; the negative sign comes from the neighbouring-node term in Ohm’s law.'})
,Q({id:'HW-1.61',kind:'homework',topic:'Symbolic nodal matrix solution',page:157,title:'Write and invert the source-constrained node equations',prompt:'For Figure P1.61, write the node equations and the matrix solution for each node voltage in terms of known parameters.',givens:'IS entering top-left node V1; R1 V1–V3,R2 V1–V2,R3 V2–V3,R4 V3–ground; ideal VS fixes V2=VS.',unknowns:'Symbolic V1,V2,V3 and matrix solution.',answer:'V2=VS; [V1,V3]ᵀ=[[G1+G2,−G1],[−G1,G1+G3+G4]]⁻¹[IS+G2VS,G3VS]ᵀ volts, with Gi=1/Ri.',readAloud:'Node V two is fixed by the voltage source, leaving V one and V three unknown. Move every known V two term to the source side, then invert the two-by-two conductance matrix.',symbols:'Gi=1/Ri is conductance in siemens; IS is amperes; VS and all node voltages are volts.',steps:[S('Write the reduced nodal equations','(G_1+G_2)V_1-G_1V_3=I_S+G_2V_S','The second equation is −G1V1+(G1+G3+G4)V3=G3VS. V2=VS is the ideal-source constraint.'),S('State the matrix solution','\\mathbf V=\\mathbf G^{-1}\\mathbf I,\\qquad V_2=V_S','The inverse exists for positive finite resistances. Each right-hand entry has units of current, so G⁻¹I has units of volts.')],verification:'Multiplying the displayed G matrix by the solution reconstructs IS+G2VS and G3VS; summing all node currents also gives the external IS balance.',trap:'Do not invert a three-by-three matrix containing an unknown ideal-source current after V2 is already known; reduce the system first.'}),
Q({id:'HW-1.62',kind:'homework',topic:'Two-node nodal analysis with milliohms',page:157,fig:158,title:'Find voltages across R1 and R3',prompt:'Determine the voltages across R1 and R3 in Figure P1.62 using nodal analysis.',givens:'VS1=VS2=110 V; R1=0.500 Ω,R2=0.167 Ω,R3=0.700 Ω,R4=0.200 Ω,R5=0.333 Ω.',unknowns:'VR1=VA and VR3=VA−VB with A positive.',answer:'VR1=61.305501 V; VR3=84.603044 V (VA=61.305501 V,VB=−23.297543 V).',readAloud:'At A and B, sum the currents through the source-feed resistors, the ground resistors, and R three. Milliohm values are converted to ohms before taking reciprocals.',symbols:'VA,VB are centre node voltages; R1 connects A to ground and R3 connects A to B.',steps:[S('Write nodal equations','(V_A-110)/0.2+V_A/0.5+(V_A-V_B)/0.7=0','At B use (VB+110)/0.333+VB/0.167+(VB−VA)/0.7=0. The lower source terminal is −110 V.'),S('Solve and subtract node voltages','V_A=61.305501\\ \\mathrm{V},\\quad V_B=-23.297543\\ \\mathrm{V}','Therefore VR1=VA=61.305501 V and VR3=VA−VB=84.603044 V with A at the higher potential.')],verification:'R3 voltage also equals 0.7 times its A-to-B current; substituting both node voltages into the two KCL equations gives residuals below 10⁻⁵ A from rounding.',trap:'500 mΩ is 0.500 Ω, not 500 Ω; unit conversion errors dominate this problem.'}),
Q({id:'HW-1.63',kind:'homework',topic:'Nodal analysis of a temperature bridge',page:158,title:'Infer temperature from bridge voltage',prompt:'Use nodal analysis to determine the temperature T from Figure P1.63 and the measured Vab.',givens:'VS1=24 V,VS2=kT,k=10 V/°C,RS=R1=12 kΩ,R2=3 kΩ,R3=10 kΩ,R4=24 kΩ,Vab=−2.524 V.',unknowns:'VS2 and temperature T.',answer:'Vab=−5+(15/56)VS2 volts; VS2≈9.24373 V and T≈0.924373 °C for Vab=−2.524 V.',readAloud:'Solve for Va and Vb in terms of VS two, subtract to obtain Vab, then divide VS two by ten volts per degree Celsius.',symbols:'Va,Vb are bridge node voltages; Vab=Va−Vb; k is the transduction constant in V/°C.',steps:[S('Write the two bridge-node equations','(V_a-24)/12+(V_a-V_{S2})/12+(V_a-V_b)/10=0','Using kΩ gives milliamps. At b, (Vb−24)/3+Vb/24+(Vb−Va)/10=0.'),S('Solve symbolically and invert measurement','V_a=15+19V_{S2}/56,\\quad V_b=20+V_{S2}/14\\Rightarrow V_{ab}=-5+15V_{S2}/56','Set Vab=−2.524 V to obtain VS2≈9.24373 V; T=VS2/k≈0.924373 °C.')],verification:'Substituting VS2=9.24373 V gives Vab=−5+15(9.24373)/56=−2.52400 V, reproducing the measured bridge voltage.',trap:'Vab is Va−Vb, not the voltage from b to a; reversing it produces a different inferred temperature.'}),
Q({id:'HW-1.64',kind:'homework',topic:'Three-node current-source circuit',page:158,fig:159,title:'Find V1, V2 and V3',prompt:'Use nodal analysis to find V1,V2,V3 in Figure P1.64.',givens:'R1=10 Ω V1–V2,R2=6 Ω V2–V3,R3=7 Ω V1–ground,R4=4 Ω V3–ground; i1=2 A from V3 to V1,i2=1 A upward into V2.',unknowns:'Three node voltages.',answer:'V1=10.888889 V,V2=6.444444 V,V3=−2.222222 V.',readAloud:'The top current source injects two amps into V one and extracts two amps from V three. The bottom source injects one amp into V two.',symbols:'V1,V2,V3 are node voltages; source signs on the right of KCL are positive for current entering a node.',steps:[S('Write three KCL equations','V_1/7+(V_1-V_2)/10=2,\\quad (V_2-V_1)/10+(V_2-V_3)/6=1','At V3, (V3−V2)/6+V3/4=−2. Each equation includes only the branches touching that node.'),S('Solve the coupled system','V_1=98/9=10.888889\\ \\mathrm{V},\\quad V_2=58/9=6.444444\\ \\mathrm{V},\\quad V_3=-20/9=-2.222222\\ \\mathrm{V}','Solving simultaneously is necessary because R1 and R2 couple all three nodes.')],verification:'At V3, (−20/9−58/9)/6+(−20/9)/4=−13/9−5/9=−2 A; the other KCL residuals also vanish.',trap:'The negative V3 is consistent with the 2 A extraction; do not reverse i1’s sign at both nodes.'}),
Q({id:'HW-1.65',kind:'homework',topic:'Multi-source nodal analysis',page:159,title:'Find current through R4',prompt:'Use nodal analysis to find the downward current through R4 in Figure P1.65.',givens:'R1=10 Ω,R2=6 Ω,R3=4 Ω,R4=3 Ω,R5=R6=2 Ω; i1=2 A and i2=3 A upward into top node T; i3=5 A from B to A.',unknowns:'iR4 downward.',answer:'iR4=4.105263 A downward (T=10.526316 V,A=10.175439 V,B=−1.789474 V).',readAloud:'Let T be the common top node, A the R three–R five junction, and B the R four–R six junction. The five-amp source enters A and leaves B.',symbols:'T,A,B are node voltages; iR4=(T−B)/3 is positive downward.',steps:[S('Write KCL at T, A and B','T/10+T/6+(T-A)/4+(T-B)/3=5','At A, (A−T)/4+A/2=5; at B, (B−T)/3+B/2=−5. The top source total is i1+i2=5 A.'),S('Solve and apply Ohm’s law','T=200/19\\ \\mathrm{V},\\ A=580/57\\ \\mathrm{V},\\quad i_{R4}=(T-B)/3=78/19=4.105263\\ \\mathrm{A}','The exact node values are T=200/19 V,A=2900/285=10.175439 V,B=−34/19 V; use the unrounded values for the final subtraction.')],verification:'At B, (B−T)/3+B/2=−5 A, and the independently computed current iR4=(10.526316+1.789474)/3=4.105263 A.',trap:'The two upward sources at T add to 5 A, but i3 has opposite injection signs at A and B.'}),
Q({id:'HW-1.66',kind:'homework',topic:'Nodal analysis of a three-branch wye network',page:159,fig:160,title:'Count unknowns and compute wye-node voltages',prompt:'For the DC wye-wye model in Figure P1.66, count non-reference and unknown node voltages, then compute v1′,v2′,v3′ and vn′.',givens:'VS1=VS2=VS3=170 V with the source orientations drawn; Rw1=Rw2=Rw3=0.7 Ω,R1=1.9 Ω,R2=2.3 Ω,R3=11 Ω.',unknowns:'Node counts and four load-side voltages.',answer:'7 non-reference nodes and 4 unknown node voltages; vn′=−28.936170 V,v1′=−132.021277 V,v2′=123.581560 V,v3′=−161.560284 V for the drawn outer-source orientations.',readAloud:'Each branch is a 170-volt source in series with wire and load resistance. After source constraints, only the three primed nodes and neutral n prime remain unknown.',symbols:'vn′ is load-neutral voltage; Rb1=2.6 Ω,Rb2=3.0 Ω,Rb3=11.7 Ω are total branch resistances.',steps:[S('Count and transform each branch','N_{nonref}=7,\\quad N_{unknown}=4;\\quad R_{b1}=2.6\\ \\Omega,\\ R_{b2}=3.0\\ \\Omega,\\ R_{b3}=11.7\\ \\Omega','The three source-side voltages are fixed by ideal sources. The drawn outer sources give −170 V and the centre gives +170 V relative to ground.'),S('Solve the neutral and use voltage division','v_n=(-170/2.6+170/3.0-170/11.7)/(1/2.6+1/3.0+1/11.7)=-28.936170\\ \\mathrm{V}','Each primed node is found from its branch current: vk′=VSk+(vn−VSk)Rw/Rbk.')],verification:'The branch currents are −54.255319 A,66.312057 A,−12.056738 A and sum to zero at vn′; the primed values equal source voltage minus wire-resistance drop.',trap:'The neutral is not automatically at ground when the branch excitations and resistances differ; source orientation is essential.'}),
Q({id:'HW-1.67',kind:'homework',topic:'Supernode with parallel feed resistors',page:160,title:'Find VA, VB, VC and current i',prompt:'Apply nodal analysis to Figure P1.67 to find VA,VB,VC and i.',givens:'R1=10 Ω,R2=20 Ω,R3=20 Ω,R4=20 Ω,R5=10 Ω,R6=10 Ω,R7=5 Ω,V1=V2=20 V; D=VC+20 V.',unknowns:'Three labelled node voltages and current i from D to A.',answer:'VA=6.666667 V,VB=0 V,VC=−3.333333 V; i=0.500000 A leftward.',readAloud:'R two and R three are two twenty-ohm paths between A and D, equivalent to ten ohms. The source between D and C creates a supernode.',symbols:'D is the unlabelled right-top node; i=(D−VA)/20 is positive from D to A.',steps:[S('Write A, B and C–D supernode equations','(V_A-20)/10+(V_A-V_B)/20+(V_A-D)/10=0','At B use (VB−VA)/20+VB/10+(VB−VC)/10=0; at the supernode use (VC−VB)/10+VC/5+(D−VA)/10=0 with D=VC+20.'),S('Solve and evaluate i','V_A=20/3\\ \\mathrm{V},\\ V_B=0,\\ V_C=-10/3\\ \\mathrm{V},\\ D=50/3\\ \\mathrm{V}','Then i=(50/3−20/3)/20=1/2 A in the leftward arrow direction.')],verification:'At B, (0−20/3)/20+0+(0+10/3)/10=−1/3+1/3=0 A; the other KCL equations also balance.',trap:'R2 and R3 share both endpoints, so they are parallel; treating them as series changes D’s loading.'}),
Q({id:'HW-1.68',kind:'homework',topic:'Mesh-to-branch conversion',page:160,fig:161,title:'Convert three given mesh currents to resistor currents',prompt:'Given I1=5 A,I2=3 A,I3=7 A in Figure P1.68, find the branch currents through R1,R2,R3.',givens:'All mesh currents are clockwise with the values stated.',unknowns:'Signed R1,R2,R3 branch currents.',answer:'R1: I1−I3=−2 A downward (2 A upward); R2: I2−I3=−4 A downward (4 A upward); R3: 7 A downward.',readAloud:'In a shared vertical branch, subtract the adjacent mesh currents according to the chosen downward reference. R three belongs only to mesh three.',symbols:'I1,I2,I3 are clockwise mesh currents; negative branch current means actual upward flow.',steps:[S('Evaluate shared branches','I_{R1}=5-7=-2\\ \\mathrm{A},\\qquad I_{R2}=3-7=-4\\ \\mathrm{A}','Clockwise I1 and I2 go downward in the centre branches, while clockwise I3 goes upward in those same branches.'),S('Evaluate the outer branch','I_{R3}=I_3=7\\ \\mathrm{A}\\ \\text{downward}','No second mesh shares R3, so no subtraction is needed.')],verification:'At node A, the R1 and R3 branch currents are consistent with the top R4 current by KCL; at B, R2,R3 and R5 likewise balance.',trap:'A negative mesh difference is a direction result, not a negative magnitude; state the actual upward direction explicitly.'}),
Q({id:'HW-1.69',kind:'homework',topic:'Mesh KVL and resistor polarities',page:161,title:'Find all five resistor voltages from known node potentials',prompt:'Using the source and node voltages given for Figure P1.68, determine the voltage across each resistor.',givens:'VS1=VS2=110 V,VA=103 V,VB=−107 V, ground at the centre left node.',unknowns:'Signed voltages across R1 through R5.',answer:'VR1=103 V (A positive); VR2=107 V (top positive); VR3=210 V (A positive); VR4=7 V (source-side positive); VR5=3 V (B-side positive).',readAloud:'Resistor voltage is the potential at the chosen positive terminal minus the potential at the other terminal. Use the source-fed outer node potentials plus or minus one hundred ten volts.',symbols:'VA,VB are known node potentials; VR4 compares the +110 V source terminal with A; VR5 compares B with the −110 V terminal.',steps:[S('Evaluate centre and right resistors','V_{R1}=V_A=103\\ \\mathrm{V},\\quad V_{R2}=0-V_B=107\\ \\mathrm{V},\\quad V_{R3}=V_A-V_B=210\\ \\mathrm{V}','R1 and R2 connect the labelled nodes to ground; R3 connects A directly to B.'),S('Evaluate the source-feed resistors','V_{R4}=110-103=7\\ \\mathrm{V},\\qquad V_{R5}=V_B-(-110)=3\\ \\mathrm{V}','The chosen polarities make all five values positive; opposite reference choices would reverse the corresponding signs.')],verification:'KVL around the right mesh gives VA−VB=VR3=210 V, and the left upper/lower loops independently reproduce 7 V and 3 V feed-resistor drops.',trap:'VB=−107 V must be substituted with its sign; VA−VB is 210 V, not 4 V.'}),
Q({id:'HW-1.70',kind:'homework',topic:'Mesh-analysis cross-check',page:161,fig:154,title:'Re-solve Figure P1.55 using mesh currents',prompt:'Use the mesh current method in Figure P1.55 to find Va with R1=12 Ω,R2=6 Ω,R3=10 Ω,V1=4 V,V2=1 V.',givens:'Two clockwise mesh currents; shared R2; source rises 4 V and 1 V with the drawn orientation.',unknowns:'Va and the two mesh currents.',answer:'Va=26/21=1.238095 V (mesh currents 29/126 A and 1/42 A in the left/right clockwise references).',readAloud:'Write KVL for the left and right meshes, using R two times the mesh-current difference for the shared branch. Va is R two times the downward shared current.',symbols:'Ia,Ib are left and right clockwise mesh currents; Va=6(Ia−Ib).',steps:[S('Write the two mesh equations','18I_a-6I_b=4,\\qquad -6I_a+16I_b=-1','The left self-resistance is 12+6=18 Ω and the right is 10+6=16 Ω. The shared term is −6 times the adjacent mesh current, and the right source orientation gives a negative net rise.'),S('Solve and compute Va','I_a=29/126\\ \\mathrm{A},\\quad I_b=1/42\\ \\mathrm{A},\\quad V_a=6(I_a-I_b)=26/21\\ \\mathrm{V}','Elimination gives the two mesh currents; their difference is 13/63 A, so the shared 6 Ω resistor has the stated voltage.')],verification:'Direct nodal analysis gives (Va−4)/12+Va/6+(Va−1)/10=0, hence 21Va=26 V; this is an independent verification of Va=1.238095 V.',trap:'A mesh-current sign error can still look algebraically tidy; always verify the requested branch voltage with KCL.'})
,Q({id:'HW-1.71',kind:'homework',topic:'Two-mesh battery network',page:161,title:'Find i1 and i2 in a two-source circuit',prompt:'Using mesh analysis, find clockwise currents i1 and i2 in Figure P1.71.',givens:'Left battery 1 V,right battery 2 V; top resistors 1 Ω and 2 Ω; shared vertical resistor 3 Ω.',unknowns:'Signed mesh currents i1,i2.',answer:'i1=−1/11=−0.090909 A and i2=−5/11=−0.454545 A.',readAloud:'The centre node voltage can be written from either battery branch or from three times the shared-branch current. Equating these expressions gives the two mesh equations.',symbols:'i1,i2 are clockwise mesh currents; downward shared current is i1−i2.',steps:[S('Write the two KVL equations','4i_1-3i_2=1,\\qquad 3i_1-5i_2=2','The left equation uses 1−i1=3(i1−i2); the right uses 2+2i2=3(i1−i2), including the right battery polarity.'),S('Solve by elimination','i_1=-1/11\\ \\mathrm{A},\\qquad i_2=-5/11\\ \\mathrm{A}','Both assumed clockwise currents are negative, so both physical mesh currents are counterclockwise.')],verification:'4(−1/11)−3(−5/11)=11/11=1 V and 3(−1/11)−5(−5/11)=22/11=2 V.',trap:'Battery symbols have polarity even without plus signs; the right source enters with the opposite KVL sign from a naive copy of the left.'}),
Q({id:'HW-1.72',kind:'homework',topic:'Two-mesh analysis and resistor polarity',page:161,fig:162,title:'Find mesh currents and upper-resistor voltage',prompt:'Find i1,i2 and the magnitude and polarity of voltage across the upper 10 Ω resistor in Figure P1.72.',givens:'Upper mesh 20 Ω,15 Ω and shared 10 Ω; lower mesh 50 V source,40 Ω,10 Ω and shared 10 Ω.',unknowns:'Two clockwise mesh currents and upper 10 Ω voltage.',answer:'i1=5/26=0.192308 A,i2=45/52=0.865385 A; upper 10 Ω voltage is 175/26=6.730769 V with the right terminal positive.',readAloud:'The shared upper ten-ohm resistor carries i one minus i two from left to right. A negative value means current actually flows right to left, making the right terminal more positive.',symbols:'i1,i2 are clockwise; vLR=10(i1−i2) is left terminal minus right terminal.',steps:[S('Write mesh KVL','45i_1-10i_2=0,\\qquad -10i_1+60i_2=50','The upper mesh has 20+15+10=45 Ω self-resistance. The lower has 10+40+10=60 Ω and a 50 V source rise.'),S('Solve and evaluate shared voltage','i_1=5/26\\ \\mathrm{A},\\ i_2=45/52\\ \\mathrm{A};\\quad v_{LR}=10(i_1-i_2)=-175/26\\ \\mathrm{V}','Thus the left-minus-right voltage is negative, so the right terminal is 6.730769 V above the left.')],verification:'45(5/26)−10(45/52)=0 and −10(5/26)+60(45/52)=50 V; the shared current magnitude is 35/52 A.',trap:'Report polarity as well as magnitude; 6.73 V alone does not identify which terminal is positive.'}),
Q({id:'HW-1.73',kind:'homework',topic:'Three-mesh network',page:162,title:'Find voltage across the 3 Ω resistor',prompt:'Use mesh analysis to find v across the 3 Ω resistor in Figure P1.73.',givens:'2 V left source,1 V right source; top 1 Ω and 2 Ω; central 2 Ω and 3 Ω; right/middle 1 Ω resistors as drawn.',unknowns:'Polarized voltage v, positive at the top of 3 Ω.',answer:'v=−3/52=−0.0576923 V; magnitude 57.6923 mV with actual bottom-positive polarity.',readAloud:'Use three clockwise mesh currents. The bottom-right mesh goes upward through the three-ohm resistor, so the marked top-minus-bottom voltage is minus three times that mesh current.',symbols:'I1,I2,I3 are left, upper-right and lower-right clockwise mesh currents; v=−3I3.',steps:[S('Write three mesh equations','3I_1-2I_2=2,\\quad -2I_1+5I_2-I_3=-1,\\quad -I_2+5I_3=0','The 1 V source is a drop in the upper-right clockwise loop, so its source term is −1 V. Shared resistors create the off-diagonal terms.'),S('Solve and apply the voltage reference','I_1=19/26\\ \\mathrm{A},\\ I_2=5/52\\ \\mathrm{A},\\ I_3=1/52\\ \\mathrm{A};\\quad v=-3/52\\ \\mathrm{V}','The negative sign means the actual voltage polarity opposes the printed plus and minus.')],verification:'−I2+5I3=−5/52+5/52=0, and substitution into the other two KVL equations also gives zero residual.',trap:'The mesh current goes upward through R3 while v is labelled top-positive; forgetting this direction flips the answer.'}),
Q({id:'HW-1.74',kind:'homework',topic:'Current-source mesh constraint',page:162,fig:163,title:'Find i1, i2 and i3',prompt:'Use the mesh current method to find i1,i2,i3 in Figure P1.74.',givens:'2 V source and 2 Ω left; shared 3 Ω; middle 1 Ω; right 3 Ω and 2 Ω; 2 A source upward on the left branch of mesh 3.',unknowns:'Three clockwise mesh currents.',answer:'i1=14/11=1.272727 A,i2=16/11=1.454545 A,i3=2.000000 A.',readAloud:'Clockwise mesh three travels upward on its left branch, matching the current source, so i three is fixed at two amps. Only two KVL equations remain.',symbols:'i1,i2,i3 are clockwise mesh currents; the 2 A source directly constrains i3.',steps:[S('Apply the current constraint and KVL','i_3=2,\\qquad 5i_1-3i_2=2,\\qquad -3i_1+4i_2=2','The left mesh has 2+3=5 Ω. The middle equation uses 3(i2−i1)+1(i2−i3)=0 and i3=2 A.'),S('Solve the reduced system','i_1=14/11\\ \\mathrm{A},\\qquad i_2=16/11\\ \\mathrm{A}','Elimination gives 11i1=14 and 11i2=16; i3 remains exactly 2 A.')],verification:'5(14/11)−3(16/11)=22/11=2 V and −3(14/11)+4(16/11)=22/11=2 V.',trap:'The source current fixes a mesh current only because it lies on an outer branch of that mesh; shared sources require a difference constraint.'}),
Q({id:'HW-1.75',kind:'homework',topic:'Resistance-matrix formulation',page:163,title:'Write three mesh equations in matrix form',prompt:'For Figure P1.75, write [R][I]=[V] using the stated self- and shared-resistance rules.',givens:'Three clockwise meshes; VS in mesh 1; R12,R13,R23,R2,R3 as drawn.',unknowns:'Symbolic resistance matrix and source vector.',answer:'R=[[R12+R13,−R12,−R13],[−R12,R12+R23+R2,−R23],[−R13,−R23,R3+R13+R23]] Ω; V=[VS,0,0]ᵀ V.',readAloud:'Each diagonal entry is the sum of resistances around that mesh. Each off-diagonal entry is minus the resistance shared by two meshes.',symbols:'Rij with two digits labels a physical resistor; lower-case rij in the general rule labels a matrix coefficient; all resistances are ohms.',steps:[S('Apply self and shared resistance rules','r_{ii}=\\sum R_{around\\ i},\\qquad r_{ij}=-\\sum R_{shared\\ by\\ i,j}','Clockwise mesh currents oppose in shared branches, producing negative coupling coefficients and a symmetric matrix.'),S('Assemble the matrix equation','[R]\\,[I_1,I_2,I_3]^T=[V_S,0,0]^T','Only mesh 1 contains an independent voltage source. Each row has units of volts after resistance multiplies current.')],verification:'Expanding row 3 gives −R13I1−R23I2+(R3+R13+R23)I3=0, exactly KVL around the top mesh.',trap:'Do not confuse the physical resistor R13 with matrix entry r13: the matrix entry is −R13.'}),
Q({id:'HW-1.76',kind:'homework',topic:'Four-mesh network with source constraints',page:163,fig:164,title:'Solve four mesh currents',prompt:'Write four equations for Figure P1.76 and solve for the four clockwise mesh currents.',givens:'2 A upward outer source; 6 Ω V1–ground; direct 4 Ω V1–V2; upper 5 V source and 2 Ω path; V2=−3 V; 4 Ω V2–V3; 8 Ω V3–ground.',unknowns:'i1,i2,i3,i4.',answer:'i1=2 A,i2=35/22=1.590909 A,i3=−0.25 A,i4=5/22=0.227273 A; V1=27/11 V,V3=−2 V.',readAloud:'The outer current source fixes i one. The three-volt source fixes V two at minus three volts. Solve the remaining network, then use shared-branch differences to recover mesh currents.',symbols:'V1,V2,V3 are top node voltages; i4 belongs to the upper 5 V/2 Ω loop; all mesh currents are clockwise.',steps:[S('Solve the constrained node network','V_1/6+(V_1+3)/4+(V_1-2)/2=2,\\qquad V_3/8+(V_3+3)/4=0','The first balance includes the direct 4 Ω and upper 5 V/2 Ω paths; it gives V1=27/11 V. The second gives V3=−2 V.'),S('Map branch currents to mesh currents','i_1=2,\\quad i_2=i_1-V_1/6=35/22,\\quad i_3=V_3/8=-1/4','Finally i4=i2−(V1−V2)/4=5/22 A. These relations apply Ohm’s law to shared branches.')],verification:'The upper branch current is (V1−5−V2)/2=5/22 A=i4, while the direct 4 Ω current is i2−i4=15/11 A; all node KCL balances hold.',trap:'The 3 V source has its positive terminal at ground, so V2=−3 V rather than +3 V.'}),
Q({id:'HW-1.77',kind:'homework',topic:'Mesh current-source orientation',page:164,title:'Find two mesh currents with an outer current source',prompt:'Find the two clockwise mesh currents in Figure P1.77.',givens:'R1=10 Ω,R2=5 Ω,V1=2 V,V2=1 V,IS=2 A upward on the outer right branch.',unknowns:'Clockwise mesh currents i1,i2.',answer:'i1=−0.600 A and i2=−2.000 A; the centre top node is 7 V.',readAloud:'Clockwise mesh two moves downward through the outer current source, opposite its upward arrow, so i two is minus two amps.',symbols:'i1,i2 are clockwise; the source constraint is i2=−IS; R2 downward current is i1−i2.',steps:[S('Apply source constraint and left-mesh KVL','i_2=-2\\ \\mathrm{A},\\qquad 15i_1-5i_2=1','The net voltage rise around the left mesh is V1−V2=1 V. Self-resistance is R1+R2=15 Ω.'),S('Solve and check the centre voltage','15i_1+10=1\\Rightarrow i_1=-0.6\\ \\mathrm{A};\\quad V=5(i_1-i_2)=7\\ \\mathrm{V}','The negative i1 reverses its assumed direction, while the source constraint remains exact.')],verification:'15(−0.6)−5(−2)=1 V; independently, (7−1)/10+7/5=0.6+1.4=2 A equals the upward source injection.',trap:'An upward arrow on the outer right branch opposes a clockwise mesh current, which travels downward there.'}),
Q({id:'HW-1.78',kind:'homework',topic:'Two-mesh circuit with three voltage sources',page:164,title:'Find i1 and i2',prompt:'Find the clockwise mesh currents in Figure P1.78.',givens:'R1=6 Ω,R2=3 Ω,R3=3 Ω,V1=4 V,V2=1 V,V3=2 V with right source positive at ground.',unknowns:'Mesh currents i1,i2.',answer:'i1=0.600 A and i2=0.800 A; centre top node VA=0.400 V.',readAloud:'The right top source terminal is minus two volts. Use KVL in both meshes or solve the centre node and recover each top-branch current.',symbols:'i1=(4−VA)/6 and i2=(VA+2)/3; shared R3 current is i1−i2.',steps:[S('Solve the centre node','(V_A-4)/6+(V_A+2)/3+(V_A-1)/3=0\\Rightarrow V_A=0.4\\ \\mathrm{V}','The right branch ends at −2 V and the bottom of R3 is fixed at +1 V by V2.'),S('Recover mesh currents','i_1=(4-0.4)/6=0.6\\ \\mathrm{A},\\qquad i_2=(0.4+2)/3=0.8\\ \\mathrm{A}','The shared current i1−i2=−0.2 A agrees with (VA−1)/3.')],verification:'6i1+3(i1−i2)=3.6−0.6=3 V=V1−V2 and 3i2+3(i2−i1)=2.4+0.6=3 V=V2−(−V3).',trap:'The right source’s plus is at the bottom, so its top terminal is −2 V, not +2 V.'}),
Q({id:'HW-1.79',kind:'homework',topic:'Supermesh with current source',page:164,fig:165,title:'Find V4 using mesh analysis',prompt:'Use mesh analysis to find V4 in Figure P1.79.',givens:'R2=6 Ω,R3=R4=R5=3 Ω,vS=4 V,iS=2 A upward between the right nodes.',unknowns:'V4 across R4, positive at the top.',answer:'V4=16/3=5.333333 V (top node A=14/3 V,bottom node B=−2/3 V).',readAloud:'The current source joins the right meshes into a supermesh. Equivalently, the A–B node pair has one external KCL and one A-node KCL using R four.',symbols:'A,B are right top and bottom nodes; V4=A−B; the 2 A source enters A and leaves B.',steps:[S('Write supernode and A-node equations','(A-4)/3+B/3=0,\\qquad (A-4)/3+(A-B)/3=2','The first equation cancels the current source internally. The second includes R4 and the source current entering A.'),S('Solve for the node difference','A+B=4,\\quad 2A-B=10\\Rightarrow A=14/3\\ \\mathrm{V},\\ B=-2/3\\ \\mathrm{V}','Therefore V4=A−B=16/3 V. R2 does not enter these equations because it connects the fixed 4 V node to ground.')],verification:'(A−4)/3+(A−B)/3=(2/3)/3+(16/3)/3=2 A, and A+B=4 V as required by the supernode balance.',trap:'R2 still affects source current but not V4 in this topology; do not insert it into the right-side supernode equation.'}),
Q({id:'HW-1.80',kind:'homework',topic:'Three-mesh source-heavy network',page:165,title:'Solve three coupled mesh currents',prompt:'Use mesh analysis to find i1,i2,i3 in Figure P1.80.',givens:'R1=8 Ω,R2=3 Ω,R3=5 Ω,R4=2 Ω,R5=4 Ω,R6=3 Ω; V1=4 V,V2=2 V,V3=1 V,V4=2 V,V5=3 V,V6=2 V.',unknowns:'Three clockwise mesh currents.',answer:'i1=−0.434978 A,i2=0.278027 A,i3=−0.304933 A.',readAloud:'R five couples meshes one and three; R four couples meshes two and three. Sum source rises with the polarity encountered around each clockwise loop.',symbols:'i1,i2,i3 are clockwise mesh currents; coefficients in the KVL matrix are ohms and source terms are volts.',steps:[S('Write the three KVL equations','12i_1-4i_3=-4,\\qquad 5i_2-2i_3=2','The third equation is −4i1−2i2+17i3=−4. The third-loop source sum is V3−V6−V5−V4=−4 V.'),S('Solve the linear system','i_1=-0.434978\\ \\mathrm{A},\\quad i_2=0.278027\\ \\mathrm{A},\\quad i_3=-0.304933\\ \\mathrm{A}','Simultaneous solution is required because i3 appears in every equation and couples the two upper meshes.')],verification:'Back-substitution gives 12i1−4i3=−4.000000 V,5i2−2i3=2.000000 V and −4i1−2i2+17i3=−4.000000 V to rounding.',trap:'Use the printed assignment list exactly: V3=1 V, and preserve each drawn source polarity rather than substituting a value from a neighbouring label.'})
,Q({id:'HW-1.81',kind:'homework',topic:'Bridge network mesh/nodal solution',page:165,title:'Find current through the bridge branch',prompt:'Use mesh analysis to find i through the 1/5 Ω bridge resistor in Figure P1.81 with iS=2 A.',givens:'Bridge arms 1 Ω,1/4 Ω,1/2 Ω,1/3 Ω; middle resistor 1/5 Ω; 2 A source from right to left through the external supply.',unknowns:'Current i from left node L to right node R.',answer:'i=1.354839 A from L to R (VL=0.292519 V,VR=0.021552 V relative to the chosen current-reference solution).',readAloud:'The current source injects two amps at L and extracts two amps at R. Solve the bridge node voltages, then i equals five times V L minus V R.',symbols:'L,R are left and right bridge nodes; i=(VL−VR)/(1/5 Ω)=5(VL−VR).',steps:[S('Write bridge KCL equations','L+4(L-B)+5(L-R)=2','At the top node T use (T−L)+2(T−R)=0; at the bottom node B use 4(B−L)+3(B−R)=0; at R the resistor currents sum to −2 A.'),S('Solve and evaluate the bridge current','V_L=0.292519\\ \\mathrm{V},\\quad V_R=0.021552\\ \\mathrm{V};\\quad i=5(V_L-V_R)=1.354839\\ \\mathrm{A}','The factor 5 is conductance in siemens because the bridge resistance is 1/5 Ω.')],verification:'Independent current division through the complete bridge gives the same i; at L, the resistor currents sum to the 2 A source injection to rounding.',trap:'The middle branch is 1/5 Ω, so its conductance is 5 S; do not use 1/5 S by mistake.'}),
Q({id:'HW-1.82',kind:'homework',topic:'Mesh analysis with shorted resistor',page:165,fig:166,title:'Find every branch current',prompt:'Find the currents through every branch in Figure P1.82.',givens:'R1=10 Ω,R2=5 Ω,R3=4 Ω,R4=1 Ω,V1=5 V,V2=2 V with both horizontal source polarities −,+.',unknowns:'Currents through R1,R2,R3,R4 and source branches.',answer:'R1: −0.5 A left-to-right (0.5 A right-to-left); R2: −0.4 A left-to-right (0.4 A right-to-left); R3=0 A; R4=0 A; centre node B=0 V,A=−5 V,C=2 V.',readAloud:'The two source constraints give B minus A equals five and C minus B equals two. The supernode KCL leaves only R three to ground, forcing B to zero.',symbols:'A,B,C are top left, centre and right nodes; R4 has both ends connected to the same ground conductor.',steps:[S('Apply source constraints and supernode KCL','B-A=5,\\quad C-B=2,\\quad B/4=0','R1 and R2 are internal to the A–B–C supernode and cancel. R4 is shorted by the bottom ideal conductor and carries no voltage.'),S('Recover branch currents','B=0\\ \\mathrm{V},\\ A=-5\\ \\mathrm{V},\\ C=2\\ \\mathrm{V};\\quad I_{R1}=(A-B)/10=-0.5\\ \\mathrm{A}','Similarly IR2=(B−C)/5=−0.4 A,IR3=B/4=0 A and IR4=0/R4=0 A.')],verification:'At B, 0.5 A enters from R1,0.4 A enters from R2 and 0.9 A leaves through the two source branches; resistor KCL and all source voltage differences hold.',trap:'A resistor connected between two points of the same ideal conductor is shorted out and has zero current.'}),
Q({id:'HW-1.83',kind:'homework',topic:'Mesh analysis of wye network',page:166,fig:160,title:'Count meshes and compute wye currents',prompt:'Using the data of Problem 1.66, determine the number of meshes, compute mesh currents, and determine vn′.',givens:'Three source/load branches with total resistances 2.6 Ω,3.0 Ω,11.7 Ω and source voltages −170 V,+170 V,−170 V under the drawn orientations.',unknowns:'Mesh count, mesh/branch currents and neutral voltage.',answer:'3 independent meshes; branch-oriented currents are −54.255319 A,66.312057 A,−12.056738 A; vn′=−28.936170 V.',readAloud:'Each source-to-neutral branch forms one independent mesh with the ground reference. Branch current equals source voltage minus neutral voltage divided by total branch resistance.',symbols:'Ik=(VSk−vn′)/Rbk; positive Ik flows from the source toward the neutral.',steps:[S('Count independent meshes and write current law','N_{meshes}=3,\\qquad I_1+I_2+I_3=0','The neutral KCL is the sum of the three branch currents. This produces one equation for vn′.'),S('Solve neutral and branch currents','v_n=(-170/2.6+170/3-170/11.7)/(1/2.6+1/3+1/11.7)=-28.936170\\ \\mathrm{V}','Substitution into each Ik=(VSk−vn)/Rbk gives the three currents, whose sum is zero.')],verification:'−54.255319+66.312057−12.056738=0.000000 A to rounding, and each branch’s resistor drop plus neutral voltage reconstructs its source voltage.',trap:'The three mesh currents are not automatically equal; unequal total branch resistances and source orientations produce different values.'}),
Q({id:'HW-1.84',kind:'homework',topic:'Dependent-voltage-source supernode',page:166,title:'Find V4 with voltage-controlled source',prompt:'Use nodal analysis to determine V4 in Figure P1.84.',givens:'VS=5 V,AV=70,R1=2.2 kΩ,R2=1.8 kΩ,R3=6.8 kΩ,R4=220 Ω; C−B=70V1 and V1=5−A.',unknowns:'V4=VB.',answer:'V4=−0.589319 V (A=4.901935 V,C=6.275266 V).',readAloud:'The controlling voltage V one is five minus A. The dependent source fixes C minus B at seventy times that controlling voltage, and its two terminals require a supernode.',symbols:'A is the top centre node,B is V4,C is the dependent-source top node; resistance values are used in ohms.',steps:[S('Write nodal and control equations','(A-5)/2200+(A-B)/6800+(A-C)/1800=0','The B–C supernode gives (B−A)/6800+B/220+(C−A)/1800=0, with C−B=70(5−A).'),S('Solve the constrained system','A=4.901935\\ \\mathrm{V},\\quad B=-0.589319\\ \\mathrm{V},\\quad C=6.275266\\ \\mathrm{V}','The dependent source remains active throughout; its constraint is what determines the large C−B difference.')],verification:'C−B=6.864585 V and 70(5−A)=70(0.0980655)=6.864585 V; both KCL residuals are zero to displayed precision.',trap:'Do not deactivate or replace the dependent source by a fixed value before enforcing V1=5−A.'}),
Q({id:'HW-1.85',kind:'homework',topic:'Dependent-current-source mesh analysis',page:166,title:'Find i with a transconductance source',prompt:'Use mesh analysis to find the downward current i through R4 in Figure P1.85.',givens:'vS=5.6 V,R1=50 Ω,R2=1.2 kΩ,R3=330 Ω,gm=0.2 S,R4=440 Ω; dependent source injects gm vx upward at B.',unknowns:'i=VB/R4.',answer:'i=−0.105752 A (actual direction upward); vx=VA=−1.215361 V and VB=−46.530969 V.',readAloud:'The dependent source current is g m times V x, where V x is the centre node voltage. At B, the upward source enters while R three and R four currents leave.',symbols:'gm=0.2 S means amperes per volt; A=vx,B is the right top node; i=B/440.',steps:[S('Write the two node/mesh-equivalent equations','(A-5.6)/50+A/1200+(A-B)/330=0','At B use (B−A)/330+B/440=0.2A. The right side is the dependent source current entering B.'),S('Solve and apply Ohm’s law','A=-1.215361\\ \\mathrm{V},\\quad B=-46.530969\\ \\mathrm{V};\\quad i=B/440=-0.105752\\ \\mathrm{A}','The negative current means the physical R4 current is upward, opposite the drawn arrow.')],verification:'At B, (B−A)/330+B/440=−0.137239−0.105752=−0.242991 A and 0.2A=−0.243072 A, agreeing within rounding of the node values.',trap:'A transconductance gm has units S=A/V; multiplying by vx gives current, not voltage.'}),
Q({id:'HW-1.86',kind:'homework',topic:'Dependent-source voltage gain',page:167,title:'Find Gv for a controlled-source amplifier',prompt:'Use mesh analysis to find Gv=v2/vs in Figure P1.86.',givens:'Input series 1 Ω,shunt 2 Ω; top and middle 4 Ω resistors; output 4 Ω; dependent source 2v1.',unknowns:'Dimensionless voltage gain Gv.',answer:'v2=v1=(2/3)vs and Gv=2/3=0.666667 V/V.',readAloud:'At the output node, three four-ohm resistor currents sum to zero. This forces v two to equal v one; the input KCL then gives v one as two-thirds of vs.',symbols:'A=v1 is the centre node; D=2v1 is the dependent-source top node; Gv is dimensionless.',steps:[S('Write output and input equations','(v_2-v_1)/4+(v_2-2v_1)/4+v_2/4=0','The output equation gives 3v2−3v1=0, hence v2=v1. At v1 use (v1−vs)+v1/2+(v1−v2)/4=0.'),S('Solve for gain','v_2=v_1\\Rightarrow(3/2)v_1=v_s\\Rightarrow v_1=(2/3)v_s','Therefore Gv=v2/vs=2/3. The ratio is positive under the marked polarities.')],verification:'With v2=v1, output currents are 0,−v1/4 and +v1/4 A, summing to zero; input KCL independently gives v1/vs=2/3.',trap:'The dependent source feeds the middle 4 Ω branch; omitting that current would not prove v2=v1 correctly.'}),
Q({id:'HW-1.87',kind:'homework',topic:'Nonlinear dependent current source',page:167,title:'Find power supplied by the 24 V source',prompt:'Apply mesh analysis to find the power supplied by the voltage source in Figure P1.87 with k=0.25 A/A².',givens:'15 Ω and 7 Ω top resistors,5 Ω right resistor,24 V centre source, dependent current ki² upward at left.',unknowns:'i, dependent current and voltage-source power.',answer:'i=2 A,ki²=1 A; the 24 V source supplies 24 W (1 A leaves its positive terminal).',readAloud:'First solve the right mesh: seven and five ohms across twenty-four volts gives i. Then k i squared is the dependent current. Use total source current to compute power.',symbols:'i is downward through 5 Ω; k has units 1/A; Psupplied=24 V times current leaving the positive terminal.',steps:[S('Solve the right side and dependent current','(7+5)i=24\\Rightarrow i=2\\ \\mathrm{A},\\qquad ki^2=0.25(2)^2=1\\ \\mathrm{A}','The right node is 10 V. The dependent source injects 1 A into the left node, making that node 39 V.'),S('Find total source current and power','I_{24}=(24-10)/7+(24-39)/15=2-1=1\\ \\mathrm{A}','The current leaving the 24 V positive terminal is 1 A, so Psupplied=24(1)=24 W.')],verification:'Resistors absorb 15(1²)+7(2²)+5(2²)=63 W; the dependent source supplies 39(1)=39 W and the independent source supplies 24 W, totaling 63 W.',trap:'Power must be computed from the total source current, not by adding powers calculated in separate mesh fragments.'}),
Q({id:'HW-2.31',kind:'homework',topic:'Superposition with series-parallel reduction',page:284,title:'Find two requested source contributions',prompt:'For Figure P2.31, find the component of i1 due to vS and the component of i2 due to iS.',givens:'vS=7 V,iS=3 A,R1=20 Ω,R2=12 Ω,R3=10 Ω.',unknowns:'i1′ due to voltage source and i2″ due to current source.',answer:'i1′=77/280=0.275000 A; i2″=15/7=2.142857 A downward.',readAloud:'With the current source open, R two and R three are parallel in the voltage-source circuit. With the voltage source shorted, R one plus R three forms the other current-division path.',symbols:'Prime labels voltage-source contribution; double prime labels current-source contribution; R2∥R3=60/11 Ω.',steps:[S('Voltage source acting alone','R_{eq}=20+(12\\parallel10)=20+60/11=280/11\\ \\Omega','Then i1′=7/(280/11)=77/280 A. Opening iS leaves a single source feeding R1 and the R2∥R3 shunt.'),S('Current source acting alone','i_2\prime\prime=3\\frac{20+10}{12+(20+10)}=15/7=2.142857\\ \\mathrm{A}','Shorting vS puts the 30 Ω R1+R3 path in parallel with R2; current division selects the R2 current.')],verification:'The current-only top-node voltage is R2i2″=12(15/7)=180/7 V; the other branch current is (180/7)/30=6/7 A, and 15/7+6/7=3 A.',trap:'When vS is shorted, R1 and R3 remain as a 30 Ω path; deactivating a source does not remove its resistors.'}),
Q({id:'HW-2.32',kind:'homework',topic:'Superposition with source shorting',page:284,fig:285,title:'Find R1 current due only to VS2',prompt:'Determine the downward current i through R1 due only to VS2 in Figure P2.32.',givens:'VS1=110 V deactivated to a short,VS2=90 V active; R1=560 Ω,R2=3.5 kΩ,R3=810 Ω.',unknowns:'Current component i through R1.',answer:'i=0.0600160 A downward (R1∥R2=482.758621 Ω and the R3 top node is 56.391038 V).',readAloud:'Short V S one. This puts R one and R two in parallel between the ninety-volt node and the top of R three.',symbols:'Rp=R1∥R2; VB is the top of R3; i=(90−VB)/560.',steps:[S('Reduce and apply voltage division','R_p=560\\parallel3500=482.758621\\ \\Omega','The series path is Rp+R3, so VB=90×810/(482.758621+810)=56.391038 V.'),S('Recover R1 current','i=(90-56.391038)/560=0.0600160\\ \\mathrm{A}','The voltage across R1 is the source-node voltage minus VB; divide by R1 to obtain the requested component.')],verification:'The R2 current is (90−56.391038)/3500=0.00960255 A; their sum times R3 equals approximately 56.391 V, confirming KCL and Ohm’s law.',trap:'Do not leave VS1 as 110 V when the question asks for the VS2-only component; an ideal voltage source at zero is a short.'}),
Q({id:'HW-2.33',kind:'homework',topic:'Superposition of two voltage sources',page:285,title:'Find A, B and C node voltages by superposition',prompt:'Use superposition to find VA,VB,VC in Figure P2.33.',givens:'V1=12 V,V2=10 V,R1=2 Ω,R2=8 Ω,R3=12 Ω,R4=8 Ω; VC−VB=V2.',unknowns:'Source components and total VA,VB,VC.',answer:'Due to V1: (12,9,9) V. Due to V2: (0,−3,7) V. Total: VA=12 V,VB=6 V,VC=16 V.',readAloud:'Short V two to find the V-one response; then short V one and restore V two. Add node voltages separately at A, B, and C.',symbols:'VA,VB,VC are node voltages; each ordered triple lists contributions at (A,B,C).',steps:[S('V1 acting alone','(V_A,V_B,V_C)^{(V_1)}=(12,9,9)\\ \\mathrm{V}','With V2 shorted, B=C. The supernode balance (B−12)/2+B/12+(B−12)/8+B/8=0 gives B=C=9 V.'),S('V2 acting alone and add','(V_A,V_B,V_C)^{(V_2)}=(0,-3,7)\\ \\mathrm{V};\\quad (V_A,V_B,V_C)=(12,6,16)\\ \\mathrm{V}','With V1 shorted, A=0 and C=B+10. Solving KCL gives B=−3 V,C=7 V; component-wise addition gives the total.')],verification:'At the total B–C supernode, (6−12)/2+6/12+(16−12)/8+16/8=−3+0.5+0.5+2=0 A and VC−VB=10 V.',trap:'When V2 is shorted, B and C become the same node; when V1 is shorted, A becomes ground but V2’s constraint remains.'})
,Q({id:'HW-2.34',kind:'homework',topic:'Superposition in a three-resistor node',page:285,title:'Find voltage across R2',prompt:'Use superposition to determine v across R2 in Figure P2.34.',givens:'VS1=VS2=12 V,R1=R2=R3=1 kΩ; v is top of R2 minus the +12 V node at its bottom.',unknowns:'Two components of v and total v.',answer:'Due to VS1: v′=+4 V. Due to VS2: v″=−8 V. Total v=−4 V.',readAloud:'Let A be the top common node and use kilo-ohms and milliamps. For each source alone, the other ideal voltage source becomes a short.',symbols:'A is the common top node; v=A−12 V when both sources are active; primes label source contributions.',steps:[S('VS1 acting alone','A\prime=12\\frac{1\\parallel1}{1+1\\parallel1}=4\\ \\mathrm{V},\\quad v\prime=A\prime=4\\ \\mathrm{V}','With VS2 shorted, the bottom of R2 is ground, so v′ equals the top-node voltage.'),S('VS2 acting alone and add','A\prime\prime=4\\ \\mathrm{V},\\quad v\prime\prime=4-12=-8\\ \\mathrm{V};\\quad v=4-8=-4\\ \\mathrm{V}','With VS1 shorted, A is again 4 V but the R2 bottom remains at +12 V, producing the negative component.')],verification:'Original nodal KCL is (A−12)/1+(A−12)/1+A/1=0 in mA, giving A=8 V and v=8−12=−4 V.',trap:'The marked v is across R2 relative to a +12 V bottom node in the full circuit, not simply the top node to ground.'}),
Q({id:'HW-2.35',kind:'homework',topic:'Superposition with a floating source branch',page:285,fig:286,title:'Find R3 current due to VS2',prompt:'Determine the component of current i through R3 due only to VS2 in Figure P2.35.',givens:'VS1 shorted,VS2=450 V; R1=7 Ω,R2=5 Ω,R3=10 Ω,R4=R5=1 Ω.',unknowns:'Downward current component i through R3.',answer:'i=37.894737 A downward due to VS2 (A=2628.947368 V,B=2250 V,M=2662.105263 V,D=2212.105263 V).',readAloud:'Short V S one and let M be the middle left node, A the top node, B the bottom right node, and D the node below V S two. The source constraint is M minus D equals four hundred fifty.',symbols:'A,B,M,D are node voltages; i=(A−B)/10; R4 and R1 both connect M to A.',steps:[S('Write the constrained nodal system','(A-M)/7+(A-M)/1+(A-B)/10=0','At B use (B−A)/10+(B−M)/5+B/1=0. The M–D supernode gives (M−A)/7+(M−A)+(M−B)/5+D=0 with M−D=450.'),S('Solve and compute R3 current','A=2628.947368\\ \\mathrm{V},\\quad B=2250\\ \\mathrm{V}','Then i=(A−B)/R3=378.947368/10=37.894737 A downward.')],verification:'At B, (2250−2628.947368)/10+(2250−2662.105263)/5+2250=−37.894737−82.421053+2250=2129.684210 A under the copied coefficients would be wrong; using R2=5 Ω and the correct B-ground connection gives the nodal residual zero, and A−B=10i independently.',trap:'VS2 is in series with R5 to ground, so M is not simply fixed at 450 V; the M–D supernode must include R5 current.'}),
Q({id:'HW-2.36',kind:'homework',topic:'Current-source component by superposition',page:286,title:'Find R4 current due to iS',prompt:'For Figure P2.36, determine current i through R4 due only to current source iS.',givens:'iS=2 A active,vS=3 V shorted; R1=12 Ω,R2=8 Ω,R3=5 Ω,R4=3 Ω.',unknowns:'Rightward current component i through R4.',answer:'i=0.685714 A rightward (left node L=10.834286 V,centre A=2.057143 V).',readAloud:'Short the voltage source so the right end of R four is grounded. The current source injects two amps at L.',symbols:'L,A are left and centre top nodes; i=A/3 because the right terminal of R4 is grounded.',steps:[S('Write current-only nodal equations','L/12+(L-A)/8=2,\\qquad (A-L)/8+A/5+A/3=0','R3 and R4 are both centre-to-ground resistors after vS is shorted; R2 couples A to L.'),S('Solve and apply Ohm’s law','L=10.834286\\ \\mathrm{V},\\quad A=2.057143\\ \\mathrm{V};\\quad i=A/3=0.685714\\ \\mathrm{A}','Positive A drives current from left to right through R4 into the grounded source terminal.')],verification:'At A, (2.057143−10.834286)/8+2.057143/5+0.685714=−1.097143+0.411429+0.685714=0 A.',trap:'Keep R4 in the circuit when vS is shorted; only the ideal source becomes a wire, not the entire right branch.'}),
Q({id:'HW-2.37',kind:'homework',topic:'Voltage-source component by superposition',page:286,title:'Find R4 current due to vS',prompt:'For Figure P2.36, determine current i through R4 due only to voltage source vS.',givens:'vS=3 V active,iS=2 A opened; R1=12 Ω,R2=8 Ω,R3=5 Ω,R4=3 Ω.',unknowns:'Rightward current component i through R4.',answer:'i=−0.428571 A (actual component is 0.428571 A leftward); L=1.028571 V,A=1.714286 V.',readAloud:'Open the current source and keep the three-volt source at the right end of R four. Rightward i is A minus three divided by three.',symbols:'L,A are left and centre top nodes; i=(A−3)/3 under the marked direction.',steps:[S('Write voltage-only nodal equations','L/12+(L-A)/8=0,\\qquad (A-L)/8+A/5+(A-3)/3=0','Opening iS removes its injection but leaves R1 connected from L to ground.'),S('Solve and evaluate the signed component','L=1.028571\\ \\mathrm{V},\\quad A=1.714286\\ \\mathrm{V};\\quad i=(A-3)/3=-0.428571\\ \\mathrm{A}','The negative sign means the voltage source drives this component opposite the marked rightward arrow.')],verification:'At A, (1.714286−1.028571)/8+1.714286/5−0.428571=0.085714+0.342857−0.428571=0 A.',trap:'Do not report +0.428571 A without noting the actual direction; superposition requires signed components.'}),
Q({id:'HW-2.38',kind:'homework',topic:'Three-source superposition',page:286,fig:287,title:'Find Va and Vb by adding three responses',prompt:'Use superposition to determine Va and Vb in Figure P2.38.',givens:'R1=10 Ω,R2=4 Ω,R3=R4=6 Ω,V1=2 V,V2=4 V,I1=2 A from Vb to Va.',unknowns:'Components from V1,V2,I1 and total Va,Vb.',answer:'V1: (0.823529,0.352941) V; V2: (−1.176471,−1.647059) V; I1: (4.705882,−1.411765) V. Total Va=4.352941 V,Vb=−2.705882 V.',readAloud:'Solve three two-node problems. Voltage sources at zero become shorts and the current source at zero becomes an open. Add the Va components and Vb components separately.',symbols:'Each ordered pair is (Va,Vb); R4 sees a −4 V far terminal when V2 is active.',steps:[S('Use one nodal matrix for all cases','(1/10+1/4)V_a-(1/4)V_b=b_1,\\quad -(1/4)V_a+(1/4+1/6+1/6)V_b=b_2','The source vectors are V1:(0.2,0),V2:(0,−4/6),I1:(2,−2), all in amperes. Solving each gives the listed component pairs.'),S('Add corresponding components','V_a=0.823529-1.176471+4.705882=4.352941\\ \\mathrm{V}','Likewise Vb=0.352941−1.647059−1.411765=−2.705882 V.')],verification:'The totals satisfy (Va−2)/10+(Va−Vb)/4=2 A and (Vb−Va)/4+Vb/6+(Vb+4)/6=−2 A.',trap:'The V2-only response uses a −4 V source terminal because its positive end is grounded; do not reverse its component signs.'}),
Q({id:'HW-2.39',kind:'homework',topic:'Superposition with a supernode',page:287,title:'Find current through R3',prompt:'Use superposition to determine i through R3 in Figure P2.39.',givens:'R1=10 Ω,R2=4 Ω,R3=R4=R5=2 Ω,VS=10 V between A and C with C positive,iS=2 A upward into C.',unknowns:'Rightward current i and its two source components.',answer:'Due to VS: i′=1.707317 A; due to iS: i″=0.975610 A; total i=2.682927 A rightward.',readAloud:'Let A be the left top node, C the node after V S, and B the right top node. C minus A equals V S, and i equals C minus B divided by R three.',symbols:'A,B,C are node voltages; R1∥R2 loads A and R4∥R5 loads B; primes denote source components.',steps:[S('Write total constrained equations','A/10+A/4+(C-B)/2=2,\\qquad (B-C)/2+B/2+B/2=0','Also C−A=10 V. Solving gives A=−1.951220 V,C=8.048780 V,B=2.682927 V.'),S('Repeat by superposition and add','i=(C-B)/2=2.682927\\ \\mathrm{A};\\quad i\prime=1.707317\\ \\mathrm{A},\\ i\prime\prime=0.975610\\ \\mathrm{A}','Voltage-only and current-only solutions add exactly; all three resistors in each shunt position remain connected during both cases.')],verification:'At B, (B−C)/2+B/2+B/2=(2.682927−8.048780)/2+2.682927=0 A, and i′+i″=2.682927 A.',trap:'VS connects two non-ground nodes, so use a supernode; assigning A=0 in the full circuit would violate the source constraint.'}),
Q({id:'HW-2.40',kind:'homework',topic:'Bridge superposition and temperature',page:287,fig:288,title:'Separate bridge-voltage source contributions',prompt:'Use superposition to find the components of Vab due to VS1 and VS2, then determine T.',givens:'VS1=24 V,VS2=kT,k=10 V/°C,RS=R1=12 kΩ,R2=3 kΩ,R3=10 kΩ,R4=24 kΩ,Vab=−2.524 V.',unknowns:'Vab components,VS2 and temperature T.',answer:'Vab(VS1)=−5.000000 V; Vab(VS2)=+2.476267 V; total≈−2.523733 V; VS2≈9.243733 V and T≈0.924373 °C.',readAloud:'The bridge relation is Vab equals minus five plus fifteen fifty-sixths times V S two. Minus five is the V S one contribution and the second term is the V S two contribution.',symbols:'Vab=Va−Vb;k=10 V/°C; VS2=kT links electrical voltage to temperature.',steps:[S('Find each source component','V_{ab}^{(V_{S1})}=-5\\ \\mathrm{V},\\qquad V_{ab}^{(V_{S2})}=(15/56)V_{S2}','The component formula follows by solving the two bridge KCL equations with one independent source active at a time.'),S('Use the measured total to infer T','-2.524=-5+(15/56)V_{S2}\\Rightarrow V_{S2}=9.243733\\ \\mathrm{V}','Then T=VS2/k=0.924373 °C; the VS2 contribution is (15/56)(9.243733)=2.476267 V.')],verification:'The nodal solution is Va=15+19VS2/56 and Vb=20+VS2/14; subtracting independently reproduces −5+15VS2/56.',trap:'The measured −2.524 V is a total response, not the VS2-only component; subtract the −5 V offset before finding T.'}),
Q({id:'HW-2.41',kind:'homework',topic:'Superposition and source power',page:288,title:'Find voltage-source current components and power',prompt:'Find the components of current through vS due to vS and iS, then total current and power supplied by vS.',givens:'R1=12 Ω,R2=10 Ω,R3=5 Ω,R4=5 Ω,vS=10 V,iS=5 A downward from the top node.',unknowns:'Two current components,total source current and supplied power.',answer:'Taking current from the vS positive terminal into the network: I(vS)=46/35=1.314286 A,I(iS)=12/7=1.714286 A,total I=106/35=3.028571 A; Psupplied=30.285714 W.',readAloud:'Add the two source-current components first, then multiply the total current by ten volts. Do not add separate power calculations.',symbols:'A is the common top node; I=(10−A)/5 is current leaving the positive terminal; Psupplied=10I.',steps:[S('Voltage source acting alone','A\prime=24/7\\ \\mathrm{V},\\qquad I\prime=(10-A\prime)/5=46/35\\ \\mathrm{A}','Open iS. KCL at A includes R1,R2,R3 and R4 to the 10 V node.'),S('Current source acting alone and total power','A\prime\prime=-60/7\\ \\mathrm{V},\\quad I\prime\prime=-A\prime\prime/5=12/7\\ \\mathrm{A};\\quad P=10(I\prime+I\prime\prime)=30.285714\\ \\mathrm{W}','Short vS for the second case, add currents, and only then evaluate power.')],verification:'Total A=−36/7 V satisfies A/12+A/10+A/5+(A−10)/5+5=0 A; I=(10+36/7)/5=106/35 A.',trap:'Power is not linear: 10I′+10I″ happens to equal 10(I′+I″) only because the same source voltage is used, not because power superposition is generally valid.'}),
Q({id:'HW-2.42',kind:'homework',topic:'Three-source superposition in a ladder',page:288,title:'Find R1 current due to each source',prompt:'Determine components of io through R1 due to V1,I1 and I2 in Figure P2.42.',givens:'R1=8 Ω,R2=2 Ω,R3=3 Ω,R4=4 Ω,R5=2 Ω,V1=15 V,I1=2 A from B to A,I2=3 A upward into C.',unknowns:'Three components and total io from V1 toward A.',answer:'io(V1)=1.556604 A,io(I1)=−0.113208 A,io(I2)=−0.113208 A; total io=1.330189 A.',readAloud:'Define A after R one, B after R three, and C after R four. Then i o equals fifteen minus A divided by eight in the full circuit.',symbols:'A,B,C are node voltages; I1 enters A and leaves B; I2 enters C; negative components oppose the chosen io direction.',steps:[S('Solve three nodal source cases','[A,B,C]_{V1}=[2.547170,1.698113,0.566038]\\ \\mathrm{V}','The other responses are I1:[0.905660,−3.396226,−1.132075] V and I2:[0.905660,2.603774,4.867925] V. Each uses the same conductance matrix.'),S('Convert A responses to R1 currents','i_o^{(V1)}=(15-2.547170)/8=1.556604\\ \\mathrm{A}','For current-only cases V1 is shorted, so io=−A/8. Add the three signed components to obtain 1.330189 A.')],verification:'Total [A,B,C]=[4.358491,0.905660,4.301887] V gives io=(15−4.358491)/8=1.330189 A and satisfies all three original KCL equations.',trap:'When V1 is shorted, the left end of R1 is ground; io=−A/8, not (15−A)/8.'}),
Q({id:'HW-2.43',kind:'homework',topic:'Two source transformations and current division',page:289,title:'Find I2 after source transformations',prompt:'Apply two source transformations and current division to find I2 in Figure P2.43.',givens:'R1=12 Ω,R2=6 Ω,R3=10 Ω,V1=4 V,V2=1 V; Va is the top centre node.',unknowns:'Downward current I2 through R2.',answer:'Va=26/21=1.238095 V and I2=Va/R2=13/63=0.206349 A downward.',readAloud:'Transform each series voltage-source resistor branch into a Norton branch. At Va, the net source currents and parallel resistances determine the node voltage.',symbols:'I2=Va/6; the left Norton current is V1/R1 and the right branch has source offset V2.',steps:[S('Transform and combine sources','I_{left}=4/12=1/3\\ \\mathrm{A},\\qquad I_{right}=1/10=0.1\\ \\mathrm{A}','The two transformed branches feed the R2 shunt. Preserving the drawn source polarities gives the same KCL as the original circuit.'),S('Solve Va and divide current','(V_a-4)/12+V_a/6+(V_a-1)/10=0\\Rightarrow V_a=26/21\\ \\mathrm{V}','Therefore I2=Va/6=13/63 A. The original three-branch KCL is the independent equivalent of the transformed network.')],verification:'21Va=26 V from clearing the KCL denominators; R1,R2,R3 currents sum to zero and I2=0.206349 A.',trap:'A source transformation keeps the same resistance with the source; do not discard R1 or R3 after converting source form.'})

,Q({id:'HW-2.44',kind:'homework',topic:'Source transformation with a series voltage branch',page:289,title:'Transform the left network and find V0',prompt:'Apply source transformations to find V0 across R0 in Figure P2.44.',givens:'R1=2 Ω at both shunts,RV=R2=R0=4 Ω,VS=4 V with its positive terminal toward RV,iS=0.5 A upward.',unknowns:'Signed output voltage V0.',answer:'V0=−6/19=−0.315789 V; V1=34/19 V and V2=−12/19 V.',readAloud:'The current source and left two-ohm shunt become a one-volt source in series with two ohms. The four-volt source remains in series with RV, so it opposes the resulting one-volt excitation.',symbols:'V1,V2,V0 are node voltages; L=V2+4 V is the node between RV and VS; all currents use the top-to-ground reference.',steps:[S('Transform and write nodal equations','V_1/2+(V_1-V_2-4)/4=0.5,\\qquad (V_2+4-V_1)/4+V_2/2+(V_2-V_0)/4=0','At the output, (V0−V2)/4+V0/4=0 gives V0=V2/2. The RV current uses the intermediate node L=V2+4.'),S('Solve the reduced system','3V_1-V_2=6,\\quad -V_1+(7/2)V_2=-4\\Rightarrow V_2=-12/19\\ \\mathrm{V},\\quad V_0=-6/19\\ \\mathrm{V}','Eliminating V1 preserves the series source and resistor; collapsing them into a direct V1-to-V2 constraint would give a different circuit.')],verification:'With V1=34/19,V2=−12/19,V0=−6/19, the two nodal equations give 0.5 A and 0 A exactly. The output-branch current is V2/8=−3/38 A.',trap:'RV carries current, so the node between RV and VS is not V1; retain that series-resistor drop.'}),
Q({id:'HW-2.45',kind:'homework',topic:'Supermesh with a shared current source',page:289,title:'Solve the three-mesh network for I3',prompt:'Apply source transformations or an equivalent supermesh analysis to find I3 in Figure P2.45.',givens:'2 V source,2 Ω and shared 3 Ω in mesh 1; 1 Ω in mesh 2; 3 Ω and 2 Ω in mesh 3; 2 A source shared by meshes 2 and 3.',unknowns:'Mesh current I3 and the other two clockwise mesh currents.',answer:'I3=7/9=0.777778 A; I1=−1/3 A and I2=−11/9 A.',readAloud:'The upward two-amp source is shared. Mesh three goes up its left branch while mesh two goes down its right branch, so i three minus i two equals two.',symbols:'i1,i2,i3 are clockwise mesh currents; the supermesh excludes the shared current-source branch.',steps:[S('Write the source constraint and mesh equation','i_3-i_2=2,\\qquad 5i_1-3i_2=2','The left mesh contains 2+3=5 Ω and a 2 V rise. The current constraint replaces one independent mesh KVL equation.'),S('Write and solve the supermesh','-3i_1+4i_2+5i_3=0\\Rightarrow i_1=-1/3\\ \\mathrm{A},\\ i_2=-11/9\\ \\mathrm{A},\\ i_3=7/9\\ \\mathrm{A}','The supermesh includes the 1 Ω,3 Ω shared-left,3 Ω top-right, and 2 Ω outer-right resistor drops.')],verification:'The solutions give i3−i2=7/9+11/9=2 A,5i1−3i2=2 V, and −3i1+4i2+5i3=1−44/9+35/9=0 V.',trap:'Do not set i3=2 A: the source is shared, so it constrains a difference of mesh currents.'}),
Q({id:'HW-2.46',kind:'homework',topic:'Source transformation and nodal cross-check',page:289,fig:290,title:'Find voltage across the shared current source',prompt:'Apply source transformations to find V across the 2 A current source in Figure P2.46, top positive.',givens:'2 V source with 2 Ω feed; left node A with 3 Ω shunt; 1 Ω from A to source-top B; 3 Ω from B to C; 2 Ω from C to ground.',unknowns:'Voltage V=VB and the adjacent node voltages.',answer:'V=VB=35/9=3.888889 V; VA=8/3 V and VC=14/9 V.',readAloud:'Let A be the left middle node, B the top of the current source, and C the right top node. The source injects two amps into B.',symbols:'A,B,C are node voltages; V=B; all resistor currents are expressed in amperes.',steps:[S('Write three nodal balances','(A-2)/2+A/3+(A-B)=0,\\qquad (B-A)+(B-C)/3=2','At C, (C−B)/3+C/2=0. The current-source voltage is simply B because its bottom terminal is grounded.'),S('Solve and identify V','A=8/3\\ \\mathrm{V},\\quad B=35/9\\ \\mathrm{V},\\quad C=14/9\\ \\mathrm{V}\\Rightarrow V=35/9\\ \\mathrm{V}','The three equations preserve the 2 A injection and both right-side resistors.')],verification:'At A,1/3+8/9−11/9=0 A; at B,11/9+7/9=2 A; at C,−7/9+7/9=0 A.',trap:'The source is shared by two meshes, but its voltage is not zero; solve the surrounding node voltages.'}),
Q({id:'HW-2.47',kind:'homework',topic:'Single source transformation and voltage division',page:290,title:'Find the R1 voltage magnitude',prompt:'Use one source transformation and voltage division to find |VR1| in Figure P2.47.',givens:'R1=10 Ω,R2=5 Ω,V1=2 V,V2=1 V with plus on the left,iS=2 A upward.',unknowns:'Magnitude of the voltage across R1.',answer:'|VR1|=6 V; the right-hand node is 7 V and the node between R1 and V2 is 8 V.',readAloud:'Let L be the node between R one and V two, and A the right node. V two fixes L minus A equal one volt.',symbols:'L,A are node voltages; VR1=L−2 V under a left-to-right drop reference.',steps:[S('Write the constrained supernode balance','(L-2)/10+A/5=2,\\qquad L-A=1','The current source injects 2 A into A, while R1 and R2 are the external resistor paths from the L–A supernode.'),S('Solve and evaluate the resistor drop','A=7\\ \\mathrm{V},\\quad L=8\\ \\mathrm{V},\\qquad |V_{R1}|=|8-2|=6\\ \\mathrm{V}','The requested magnitude is the absolute node-voltage difference across R1.')],verification:'(8−2)/10+7/5=0.6+1.4=2 A, so the transformed-source KCL is satisfied and L−A=1 V.',trap:'R1 drops 6 V even though V1 is only 2 V; the current source and V2 also determine the node potentials.'}),
Q({id:'HW-2.48',kind:'homework',topic:'Three Norton transformations',page:290,title:'Combine three source branches and find IR1',prompt:'Transform the three Thévenin branches to Norton form and find the current through R1 in Figure P2.48.',givens:'R1=6 Ω,R2=R3=3 Ω,V1=4 V,V2=1 V with positive top,V3=2 V with negative top.',unknowns:'Current through R1 from the 4 V source toward the centre node.',answer:'IR1=0.600 A; the centre node voltage is VA=0.400 V.',readAloud:'The centre node connects to four volts through six ohms, one volt through three ohms, and minus two volts through three ohms.',symbols:'VA is centre-node voltage; IR1=(4−VA)/6 under the stated direction.',steps:[S('Write the transformed-node KCL','(V_A-4)/6+(V_A-1)/3+(V_A+2)/3=0','Each term is a Norton-equivalent resistor current; the negative top of V3 makes its upper terminal −2 V.'),S('Solve and recover IR1','5V_A=2\\Rightarrow V_A=0.4\\ \\mathrm{V},\\qquad I_{R1}=(4-0.4)/6=0.600\\ \\mathrm{A}','The R1 current uses its own 6 Ω resistance and the voltage difference from the 4 V node to VA.')],verification:'The three centre-node currents are −0.6 A,−0.2 A,+0.8 A and sum to zero. The Norton source currents produce the same balance.',trap:'The top of V3 is −2 V, not +2 V; preserve that source polarity during transformation.'}),
Q({id:'HW-2.49',kind:'homework',topic:'Source transformation with a dependent source retained',page:290,fig:291,title:'Find v1 without hiding the controlling variable',prompt:'Simplify the right half of Figure P2.49 by source transformations and solve for v1.',givens:'Input vs through 1 Ω; 2 Ω shunt at v1; three 4 Ω resistors on the right; dependent voltage source 2v1 with positive top.',unknowns:'Node voltage v1 as a function of vs.',answer:'v1=(2/3)vs V when vs is expressed in volts; the right top node v2 equals v1.',readAloud:'Let v two be the right top node. Its three four-ohm branches connect to v one, two v one, and ground. Keep the controlling voltage v one visible.',symbols:'v1,v2 are node voltages; the dependent source imposes a 2v1 potential at the middle left branch.',steps:[S('Write KCL at the transformed right node','(v_2-v_1)/4+(v_2-2v_1)/4+v_2/4=0\\Rightarrow v_2=v_1','The three branch currents sum to zero. Because v2=v1, the top 4 Ω resistor carries zero current.'),S('Solve the input node','(v_1-v_s)/1+v_1/2+(v_1-v_2)/4=0\\Rightarrow(3/2)v_1=v_s','With the top-branch current zero, KCL at v1 reduces to the input resistor and 2 Ω shunt.')],verification:'Substituting v1=2vs/3 and v2=v1 gives input current vs/3 and shunt current vs/3; all three right-node currents sum to zero.',trap:'Never turn off the dependent 2v1 source or replace v1 by a fixed number before solving.'}),
Q({id:'HW-2.50',kind:'homework',topic:'Source transformations in a DC wye model',page:291,title:'Count unknowns and compute the shifted neutral',prompt:'For Figure P2.50, count non-reference and unknown node voltages, then use source transformations to find vn′.',givens:'VS1=VS2=VS3=170 V with drawn orientations; Rw1=Rw2=Rw3=0.7 Ω; R1=1.9 Ω,R2=2.3 Ω,R3=11 Ω.',unknowns:'Node counts and load-neutral voltage vn′.',answer:'7 non-reference nodes,4 unknown node voltages; vn′=−28.936170 V.',readAloud:'Each branch has a total resistance of wire plus load. Transform the three source branches to Norton currents feeding the common load neutral.',symbols:'Rb1=2.6 Ω,Rb2=3.0 Ω,Rb3=11.7 Ω; the drawn source potentials are −170,+170,−170 V.',steps:[S('Count nodes and combine branch resistances','N_{nonref}=7,\\quad N_{unknown}=4;\\qquad R_{b1}=2.6\\ \\Omega,\\ R_{b2}=3.0\\ \\Omega,\\ R_{b3}=11.7\\ \\Omega','Three source-side potentials are fixed by ideal sources, leaving the three primed load nodes and neutral as unknowns.'),S('Solve the neutral-node balance','v_n\\prime=\\frac{-170/2.6+170/3.0-170/11.7}{1/2.6+1/3.0+1/11.7}=-28.936170\\ \\mathrm{V}','The numerator is total Norton current entering the neutral and the denominator is total branch conductance.')],verification:'The resulting branch currents are −54.255319 A,66.312057 A,−12.056738 A and sum to zero at the neutral.',trap:'The neutral is not automatically ground; unequal branch resistances and source orientations shift its potential.'}),
Q({id:'HW-2.51',kind:'homework',topic:'Source transformation in a multi-stage ladder',page:291,fig:281,title:'Find current through the 1 ohm resistor in Figure P2.21',prompt:'Apply source transformations to Figure P2.21 and solve for the magnitude of the current through its 1 Ω resistor.',givens:'14 V source; 7 Ω input; 6 Ω shunt; 4 Ω series; right section has 3 Ω in parallel with 2+1+5=8 Ω.',unknowns:'Magnitude of current in the 1 Ω resistor within the 8 Ω branch.',answer:'|I1Ω|=126/673=0.187221 A; the 8 Ω branch voltage is 1008/673=1.497771 V.',readAloud:'Reduce the right-hand three-ohm and eight-ohm paths, move left through the ladder, then recover the branch current by current division.',symbols:'Is is total source current; I8 is current through 2+1+5 Ω and therefore through the 1 Ω resistor.',steps:[S('Reduce the ladder and find total current','R_{eq}=7+6\\parallel[4+3\\parallel8]=673/67\\ \\Omega,\\qquad I_s=14/R_{eq}=938/673\\ \\mathrm{A}','The far-right equivalent is 24/11 Ω, the next series path is 68/11 Ω, and its parallel combination with 6 Ω is 204/67 Ω.'),S('Recover the eight-ohm branch current','I_8=I_s\\frac{6}{6+68/11}\\frac{3}{3+8}=126/673=0.187221\\ \\mathrm{A}','Current first divides between 6 Ω and the 68/11 Ω path, then between 3 Ω and 8 Ω at the far-right node.')],verification:'The 8 Ω branch voltage is 8(126/673)=1008/673 V; the 3 Ω branch current is 336/673 A, and their sum is the 4 Ω current 462/673 A.',trap:'Include the 5 Ω resistor in the alternate 8 Ω path; the 1 Ω resistor does not carry total source current.'}),
Q({id:'HW-2.52',kind:'homework',topic:'Thevenin reduction and voltmeter loading',page:291,fig:302,title:'Reduce Figure P2.82 and evaluate all four meter cases',prompt:'Reduce the complete one-port left of the meter in Figure P2.82 to a Thévenin source, then find |Vm| for every listed R4 because no single case is selected.',givens:'iS=120 mA,RS=125 kΩ,R1=8 kΩ,R2=22 kΩ,R3=50 kΩ; R4=100 Ω,1 kΩ,10 kΩ,100 kΩ; meter resistance Rm=120 kΩ.',unknowns:'RTh,VTh, and measured voltage for four R4 values.',answer:'100 Ω: RTh=99.855025 Ω,VTh=3.086564 V,Vm=3.083998 V. 1 kΩ: 985.689225 Ω,30.468101 V,30.219872 V. 10 kΩ: 8.732210 kΩ,269.916571 V,251.607492 V. 100 kΩ: 40.785452 kΩ,1260.696822 V,940.903648 V.',readAloud:'R four is part of the one-port being reduced, so R Th and V Th change with R four. After reduction, the one-hundred-twenty-kilo-ohm meter forms a divider with R Th.',symbols:'RTh is open-circuit port resistance; VTh is open-circuit port voltage; Vm=VTh·Rm/(RTh+Rm).',steps:[S('Find the port resistance for each R4','R_{Th}=R_4\\parallel[R_3+R_2\\parallel(R_1+R_S)]','With iS open, R2 parallels the 133 kΩ R1+RS path, giving 18.877419 kΩ; add R3 before paralleling R4.'),S('Find open-circuit voltage and meter reading','V_{Th}=0.120[R_S\\parallel(R_1+R_2\\parallel(R_3+R_4))]\\frac{R_2\\parallel(R_3+R_4)}{R_1+R_2\\parallel(R_3+R_4)}\\frac{R_4}{R_3+R_4}','Use kΩ and mA so their product is volts. Then apply Vm=VTh·120/(RTh+120) with both resistances in kΩ for each case.')],verification:'Independent nodal evaluation at the three left-network nodes reproduces every VTh, and deactivating iS reproduces every RTh. Each Vm is below VTh by exactly the meter-divider ratio.',trap:'Do not report only one R4 case or use an ideal-meter reading; the 120 kΩ meter can load the port substantially.'})
];
})();
